insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the remainder when 1! + 2! + 3! + ... + 50! is divided by 12?','1! + 2! + 3! + ... + 50! को 12 से भाग देने पर शेषफल क्या होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "3", "body_hi": "3", "isCorrect": false}, {"id": "d", "body": "9", "body_hi": "9", "isCorrect": true}]'::jsonb,2.5,0.83,'From 4! = 24 onwards every factorial contains 4! and so is a multiple of 12. Only 1! + 2! + 3! = 1 + 2 + 6 = 9 is left over, and 9 is less than 12, so the remainder is 9. 0 assumes every term is a multiple of 12 and misses the first three; 3 stops at 1! + 2!, forgetting that 3! = 6 is not a multiple of 12; 1 counts 1! alone.','4! = 24 से आगे हर क्रमगुणित में 4! शामिल है, इसलिए वह 12 का गुणज है। केवल 1! + 2! + 3! = 1 + 2 + 6 = 9 बचता है, और 9, 12 से छोटा है, अतः शेषफल 9 है। 0 मान लेता है कि हर पद 12 का गुणज है और पहले तीन पद भूल जाता है; 3, 1! + 2! पर रुक जाता है, यह भूलकर कि 3! = 6, 12 का गुणज नहीं है; 1 केवल 1! गिनता है।','csat-l2-t03-qa-nt-factorial-sum-mod-12','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','The monthly incomes of A and B are in the ratio 5 : 4, and their monthly expenditures in the ratio 3 : 2. If each of them saves ₹1,600 a month, what is A''s monthly income?','A और B की मासिक आय 5 : 4 के अनुपात में है, और उनका मासिक व्यय 3 : 2 के अनुपात में। यदि दोनों में से प्रत्येक हर महीने ₹1,600 बचाता है, तो A की मासिक आय क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "₹2,400", "body_hi": "₹2,400", "isCorrect": false}, {"id": "b", "body": "₹3,200", "body_hi": "₹3,200", "isCorrect": false}, {"id": "c", "body": "₹4,000", "body_hi": "₹4,000", "isCorrect": true}, {"id": "d", "body": "₹8,000", "body_hi": "₹8,000", "isCorrect": false}]'::jsonb,2.5,0.83,'Let the incomes be 5x and 4x and the expenditures 3y and 2y. Then 5x - 3y = 1600 and 4x - 2y = 1600. Multiplying the second by 3/2 gives 6x - 3y = 2400; subtracting the first leaves x = 800, and then y = 800. A earns ₹4,000 and spends ₹2,400; B earns ₹3,200 and spends ₹1,600; each saves ₹1,600. ₹2,400 is A''s spending and ₹3,200 B''s income; ₹8,000 treats the ₹1,600 saving as one part of the 5 : 4 ratio.','आय 5x और 4x तथा व्यय 3y और 2y मानिए। तब 5x - 3y = 1600 और 4x - 2y = 1600। दूसरे को 3/2 से गुणा करने पर 6x - 3y = 2400; इसमें से पहला घटाने पर x = 800, और फिर y = 800। A ₹4,000 कमाता और ₹2,400 ख़र्च करता है; B ₹3,200 कमाता और ₹1,600 ख़र्च करता है; दोनों ₹1,600 बचाते हैं। ₹2,400, A का व्यय है और ₹3,200, B की आय; ₹8,000, ₹1,600 की बचत को 5 : 4 अनुपात का एक भाग मान लेता है।','csat-l2-t03-qa-rm-incomes-and-expenditures','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','statement_based','easy','Statement: Several cases of dengue have been reported from one ward of a town after a spell of heavy rain.

Which of the following courses of action logically follow(s)?','कथन: भारी वर्षा के एक दौर के बाद एक कस्बे के एक वार्ड से डेंगू के कई मामले सामने आए हैं।

निम्नलिखित में से कौन-सी कार्यवाही/कार्यवाहियाँ तार्किक रूप से अनुसरणीय है/हैं?','{"statements": ["The municipality should clear stagnant water in the ward and spray it against mosquitoes.", "All the residents of the ward should be moved to another part of the town."], "statements_hi": ["नगरपालिका को वार्ड में जमा पानी हटाना चाहिए और मच्छरों के विरुद्ध छिड़काव करना चाहिए।", "वार्ड के सभी निवासियों को कस्बे के किसी दूसरे भाग में भेज देना चाहिए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l2-t03", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": true}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only I follows. Dengue spreads through mosquitoes that breed in stagnant water, so clearing the water and spraying deal with the cause where it is. II does not follow: moving a whole ward is impractical and out of proportion, and it is the mosquitoes, not the place, that carry the disease. A course of action must be practical and must address the problem.','केवल I अनुसरणीय है। डेंगू उन मच्छरों से फैलता है जो जमा पानी में पनपते हैं, इसलिए पानी हटाना और छिड़काव करना कारण से वहीं निपटते हैं जहाँ वह है। II अनुसरणीय नहीं है: पूरे वार्ड को हटाना अव्यावहारिक और अनुपात से बाहर है, और रोग मच्छर फैलाते हैं, स्थान नहीं। कार्यवाही व्यावहारिक होनी चाहिए और समस्या को सुलझाने वाली होनी चाहिए।','csat-l2-t03-lr-sc-dengue-course-of-action','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','easy','A train 150 m long passes a pole in 15 seconds and a platform in 25 seconds. How long is the platform?','150 मीटर लंबी एक रेलगाड़ी एक खंभे को 15 सेकंड में और एक प्लेटफ़ॉर्म को 25 सेकंड में पार करती है। प्लेटफ़ॉर्म कितना लंबा है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "100 m", "body_hi": "100 मीटर", "isCorrect": true}, {"id": "b", "body": "150 m", "body_hi": "150 मीटर", "isCorrect": false}, {"id": "c", "body": "250 m", "body_hi": "250 मीटर", "isCorrect": false}, {"id": "d", "body": "375 m", "body_hi": "375 मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'Passing a pole, the train covers its own length: 150 m in 15 s, so its speed is 10 m/s. Passing the platform it covers its own length and the platform''s: 10 × 25 = 250 m, so the platform is 250 - 150 = 100 m. 250 m forgets to take away the train''s own length; 150 m is the train itself; 375 m scales the train''s length by 25/10, as if the times measured the platform alone.','खंभा पार करते समय रेलगाड़ी अपनी लंबाई तय करती है: 15 सेकंड में 150 मीटर, अतः उसकी चाल 10 मीटर/सेकंड है। प्लेटफ़ॉर्म पार करते समय वह अपनी और प्लेटफ़ॉर्म की लंबाई तय करती है: 10 × 25 = 250 मीटर, अतः प्लेटफ़ॉर्म 250 - 150 = 100 मीटर है। 250 मीटर रेलगाड़ी की अपनी लंबाई घटाना भूल जाता है; 150 मीटर स्वयं रेलगाड़ी है; 375 मीटर रेलगाड़ी की लंबाई को 25/10 से गुणा करता है, मानो समय केवल प्लेटफ़ॉर्म को मापते हों।','csat-l2-t03-qa-sdt-pole-and-platform','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','In a class, 25 students play cricket, 20 play football and 10 play both games. How many students are there in the class?','एक कक्षा में 25 विद्यार्थी क्रिकेट खेलते हैं, 20 फ़ुटबॉल खेलते हैं और 10 दोनों खेल खेलते हैं। कक्षा में कितने विद्यार्थी हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "35", "body_hi": "35", "isCorrect": false}, {"id": "b", "body": "45", "body_hi": "45", "isCorrect": false}, {"id": "c", "body": "55", "body_hi": "55", "isCorrect": false}, {"id": "d", "body": "Cannot be determined", "body_hi": "निर्धारित नहीं किया जा सकता", "isCorrect": true}]'::jsonb,2.5,0.83,'The data give the number who play at least one of the games: 25 + 20 - 10 = 35. They say nothing about students who play neither, so the class may have 35 students or more, and its size cannot be determined. 35 is the trap answer, true only if every student played one of the games; 45 forgets to take away the 10 counted twice; 55 adds them instead.','आँकड़े यह बताते हैं कि कम से कम एक खेल खेलने वाले कितने हैं: 25 + 20 - 10 = 35। वे उन विद्यार्थियों के बारे में कुछ नहीं कहते जो कोई भी खेल नहीं खेलते, इसलिए कक्षा में 35 या उससे अधिक विद्यार्थी हो सकते हैं, और उसका आकार निर्धारित नहीं किया जा सकता। 35 जाल वाला उत्तर है, जो तभी सही होता जब हर विद्यार्थी कोई एक खेल खेलता; 45, दो बार गिने गए 10 को घटाना भूल जाता है; 55 उन्हें घटाने के बजाय जोड़ देता है।','csat-l2-t03-qa-ph-class-size-not-given','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Every autumn, farmers in the north-west burn the straw left in their fields after the rice harvest, and the smoke adds to the haze that settles over the plains. Burning is not a habit that farmers cling to out of ignorance. The gap between harvesting rice and sowing wheat is barely three weeks, the straw is bulky and of little value as fodder, and removing it by machine costs money and time that a small farmer rarely has. Fines have done little, because a farmer who cannot sow on time loses far more than the fine. Where the problem has eased, it is because the alternatives became cheaper or quicker than the match: machines that sow wheat straight through the straw, supplied through cooperatives, and buyers who pay for straw as fuel or raw material.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हर शरद ऋतु में उत्तर-पश्चिम के किसान धान की कटाई के बाद खेतों में बचा पुआल जला देते हैं, और उसका धुआँ मैदानों पर छाने वाली धुंध को और बढ़ा देता है। जलाना ऐसी आदत नहीं है जिससे किसान अज्ञानवश चिपके हों। धान की कटाई और गेहूँ की बुआई के बीच मुश्किल से तीन सप्ताह होते हैं, पुआल भारी-भरकम है और चारे के रूप में उसका मूल्य कम है, और मशीन से उसे हटाने में पैसा और समय लगता है जो छोटे किसान के पास शायद ही होता है। जुर्मानों से बहुत कम हुआ है, क्योंकि जो किसान समय पर बुआई नहीं कर पाता, उसका नुक़सान जुर्माने से कहीं अधिक होता है। जहाँ समस्या घटी है, वहाँ इसलिए घटी है कि विकल्प माचिस की तीली से सस्ते या तेज़ हो गए: पुआल के बीच से ही सीधे गेहूँ बोने वाली मशीनें, जो सहकारी समितियों के माध्यम से मिलीं, और ऐसे ख़रीदार जो पुआल का ईंधन या कच्चे माल के रूप में दाम देते हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "Farmers burn their straw because they do not understand the harm that the smoke does.", "body_hi": "किसान पुआल इसलिए जलाते हैं क्योंकि वे धुएँ से होने वाली हानि को नहीं समझते।", "isCorrect": false}, {"id": "b", "body": "Burning falls where the alternatives become cheaper or quicker for farmers than burning.", "body_hi": "जलाना वहाँ घटता है जहाँ किसानों के लिए विकल्प जलाने से सस्ते या तेज़ हो जाते हैं।", "isCorrect": true}, {"id": "c", "body": "Heavier fines on farmers are the most effective way to put an end to stubble burning.", "body_hi": "किसानों पर भारी जुर्माने पुआल जलाना बंद कराने का सबसे प्रभावी तरीका हैं।", "isCorrect": false}, {"id": "d", "body": "Rice should no longer be grown in the north-west, so that there is no straw left to burn.", "body_hi": "उत्तर-पश्चिम में धान उगाना ही बंद कर देना चाहिए, ताकि जलाने के लिए कोई पुआल ही न बचे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage rejects ignorance as the cause, explains burning by the time and cost of the alternatives, and ends by saying that the problem eased where the alternatives became cheaper or quicker. Ignorance is the very explanation the passage denies; fines are said to have done little; and giving up rice is never proposed.','परिच्छेद अज्ञान को कारण मानने से इनकार करता है, जलाने की व्याख्या विकल्पों के समय और लागत से करता है, और अंत में कहता है कि समस्या वहाँ घटी जहाँ विकल्प सस्ते या तेज़ हो गए। अज्ञान ठीक वही व्याख्या है जिसे परिच्छेद नकारता है; जुर्मानों के बारे में कहा गया है कि उनसे बहुत कम हुआ; और धान छोड़ने का प्रस्ताव कहीं नहीं है।','csat-l2-t03-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Every autumn, farmers in the north-west burn the straw left in their fields after the rice harvest, and the smoke adds to the haze that settles over the plains. Burning is not a habit that farmers cling to out of ignorance. The gap between harvesting rice and sowing wheat is barely three weeks, the straw is bulky and of little value as fodder, and removing it by machine costs money and time that a small farmer rarely has. Fines have done little, because a farmer who cannot sow on time loses far more than the fine. Where the problem has eased, it is because the alternatives became cheaper or quicker than the match: machines that sow wheat straight through the straw, supplied through cooperatives, and buyers who pay for straw as fuel or raw material.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हर शरद ऋतु में उत्तर-पश्चिम के किसान धान की कटाई के बाद खेतों में बचा पुआल जला देते हैं, और उसका धुआँ मैदानों पर छाने वाली धुंध को और बढ़ा देता है। जलाना ऐसी आदत नहीं है जिससे किसान अज्ञानवश चिपके हों। धान की कटाई और गेहूँ की बुआई के बीच मुश्किल से तीन सप्ताह होते हैं, पुआल भारी-भरकम है और चारे के रूप में उसका मूल्य कम है, और मशीन से उसे हटाने में पैसा और समय लगता है जो छोटे किसान के पास शायद ही होता है। जुर्मानों से बहुत कम हुआ है, क्योंकि जो किसान समय पर बुआई नहीं कर पाता, उसका नुक़सान जुर्माने से कहीं अधिक होता है। जहाँ समस्या घटी है, वहाँ इसलिए घटी है कि विकल्प माचिस की तीली से सस्ते या तेज़ हो गए: पुआल के बीच से ही सीधे गेहूँ बोने वाली मशीनें, जो सहकारी समितियों के माध्यम से मिलीं, और ऐसे ख़रीदार जो पुआल का ईंधन या कच्चे माल के रूप में दाम देते हैं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Most farmers would go on burning straw even if a cheaper alternative were available.", "Farmers burn straw mainly because they are unaware of the harm the smoke does."], "statements_hi": ["सस्ता विकल्प उपलब्ध होने पर भी अधिकांश किसान पुआल जलाते रहेंगे।", "किसान पुआल मुख्यतः इसलिए जलाते हैं क्योंकि वे धुएँ से होने वाली हानि से अनजान हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1 runs against the passage''s own evidence: where cheaper or quicker alternatives appeared, burning eased. 2 contradicts the passage directly: ''Burning is not a habit that farmers cling to out of ignorance.''','कोई भी वैध नहीं है। 1 परिच्छेद के अपने प्रमाण के विरुद्ध जाता है: जहाँ सस्ते या तेज़ विकल्प आए, वहाँ जलाना घटा। 2 परिच्छेद का सीधा खंडन करता है: ''जलाना ऐसी आदत नहीं है जिससे किसान अज्ञानवश चिपके हों।''','csat-l2-t03-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Every autumn, farmers in the north-west burn the straw left in their fields after the rice harvest, and the smoke adds to the haze that settles over the plains. Burning is not a habit that farmers cling to out of ignorance. The gap between harvesting rice and sowing wheat is barely three weeks, the straw is bulky and of little value as fodder, and removing it by machine costs money and time that a small farmer rarely has. Fines have done little, because a farmer who cannot sow on time loses far more than the fine. Where the problem has eased, it is because the alternatives became cheaper or quicker than the match: machines that sow wheat straight through the straw, supplied through cooperatives, and buyers who pay for straw as fuel or raw material.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हर शरद ऋतु में उत्तर-पश्चिम के किसान धान की कटाई के बाद खेतों में बचा पुआल जला देते हैं, और उसका धुआँ मैदानों पर छाने वाली धुंध को और बढ़ा देता है। जलाना ऐसी आदत नहीं है जिससे किसान अज्ञानवश चिपके हों। धान की कटाई और गेहूँ की बुआई के बीच मुश्किल से तीन सप्ताह होते हैं, पुआल भारी-भरकम है और चारे के रूप में उसका मूल्य कम है, और मशीन से उसे हटाने में पैसा और समय लगता है जो छोटे किसान के पास शायद ही होता है। जुर्मानों से बहुत कम हुआ है, क्योंकि जो किसान समय पर बुआई नहीं कर पाता, उसका नुक़सान जुर्माने से कहीं अधिक होता है। जहाँ समस्या घटी है, वहाँ इसलिए घटी है कि विकल्प माचिस की तीली से सस्ते या तेज़ हो गए: पुआल के बीच से ही सीधे गेहूँ बोने वाली मशीनें, जो सहकारी समितियों के माध्यम से मिलीं, और ऐसे ख़रीदार जो पुआल का ईंधन या कच्चे माल के रूप में दाम देते हैं।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["Farmers weigh the cost of a fine against what they would lose by sowing late.", "Farmers do not care about the smoke that burning produces."], "statements_hi": ["किसान जुर्माने की लागत को उस नुक़सान के सामने तौलते हैं जो देर से बुआई करने पर होगा।", "किसानों को जलाने से उठने वाले धुएँ की परवाह नहीं है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p01", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is assumed. The claim that fines fail ''because a farmer who cannot sow on time loses far more than the fine'' makes sense only if farmers set the fine against what sowing late would cost them. 2 is not needed: the passage explains burning by time and money, not by indifference to the smoke.','केवल 1 पूर्वधारणा है। यह दावा कि जुर्माने इसलिए विफल हैं ''क्योंकि जो किसान समय पर बुआई नहीं कर पाता, उसका नुक़सान जुर्माने से कहीं अधिक होता है'', तभी अर्थपूर्ण है जब किसान जुर्माने को देर से बुआई की लागत के सामने तौलते हों। 2 की ज़रूरत नहीं: परिच्छेद जलाने की व्याख्या समय और पैसे से करता है, धुएँ के प्रति उदासीनता से नहीं।','csat-l2-t03-rc-p01-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','The price of sugar rises by 25%. By what percentage must a family cut its consumption of sugar so that its spending on sugar does not change?','चीनी का मूल्य 25% बढ़ जाता है। एक परिवार को चीनी की खपत कितने प्रतिशत घटानी होगी ताकि चीनी पर उसका ख़र्च न बदले?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "20%", "body_hi": "20%", "isCorrect": true}, {"id": "b", "body": "25%", "body_hi": "25%", "isCorrect": false}, {"id": "c", "body": "75%", "body_hi": "75%", "isCorrect": false}, {"id": "d", "body": "80%", "body_hi": "80%", "isCorrect": false}]'::jsonb,2.5,0.83,'Spending = price × quantity. If the price becomes 5/4 of what it was, the quantity must become 4/5 of what it was to keep the product the same: a cut of 1/5, or 20%. 25% copies the price rise, but a 25% cut at a price 25% higher leaves spending at 125% × 75% = 93.75%; 80% is the new level of consumption, not the cut; 75% is simply 100 - 25.','ख़र्च = मूल्य × मात्रा। यदि मूल्य पहले का 5/4 हो जाए, तो गुणनफल वही रखने के लिए मात्रा पहले की 4/5 होनी चाहिए: 1/5, यानी 20% की कटौती। 25% मूल्य वृद्धि की ही नक़ल करता है, पर 25% ऊँचे मूल्य पर 25% कटौती से ख़र्च 125% × 75% = 93.75% रह जाता है; 80% खपत का नया स्तर है, कटौती नहीं; 75% केवल 100 - 25 है।','csat-l2-t03-qa-pp-price-up-consumption-down','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','Eight people sit in two rows of four, each person directly facing one person in the other row. P, Q, R and S sit in the northern row, facing south; W, X, Y and Z sit in the southern row, facing north. Q sits at one end of the northern row, and X faces Q. R sits second to the right of Q. Y sits to the immediate left of X. Z faces R, and S does not face Y. Who faces P?','आठ लोग चार-चार की दो पंक्तियों में इस प्रकार बैठे हैं कि हर व्यक्ति दूसरी पंक्ति के ठीक एक व्यक्ति के सामने है। P, Q, R और S उत्तरी पंक्ति में दक्षिण की ओर मुँह करके बैठे हैं; W, X, Y और Z दक्षिणी पंक्ति में उत्तर की ओर मुँह करके बैठे हैं। Q उत्तरी पंक्ति के एक छोर पर बैठा है, और X, Q के सामने है। R, Q के दाएँ से दूसरे स्थान पर है। Y, X के ठीक बाएँ बैठा है। Z, R के सामने है, और S, Y के सामने नहीं है। P के सामने कौन है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "W", "body_hi": "W", "isCorrect": false}, {"id": "b", "body": "X", "body_hi": "X", "isCorrect": false}, {"id": "c", "body": "Y", "body_hi": "Y", "isCorrect": true}, {"id": "d", "body": "Z", "body_hi": "Z", "isCorrect": false}]'::jsonb,2.5,0.83,'Number the seats 1 to 4 from west to east. The northern row faces south, so its right is west; the southern row faces north, so its right is east. Second to Q''s right means two seats to the west, which is possible only if Q is at the eastern end, seat 4: so R is in seat 2, and X, facing Q, is in seat 4 of the southern row. Y, to X''s immediate left, is in seat 3, and Z, facing R, in seat 2, leaving W in seat 1. S may not face Y, so S takes seat 1 and P seat 3, opposite Y. W faces S, X faces Q and Z faces R. Taking ''right'' as east for the northern row puts Q at the wrong end.','सीटों को पश्चिम से पूर्व 1 से 4 तक गिनिए। उत्तरी पंक्ति दक्षिण की ओर देखती है, इसलिए उसका दायाँ पश्चिम है; दक्षिणी पंक्ति उत्तर की ओर देखती है, इसलिए उसका दायाँ पूर्व है। Q के दाएँ से दूसरे का अर्थ है दो सीट पश्चिम, जो तभी संभव है जब Q पूर्वी छोर, सीट 4, पर हो: अतः R सीट 2 पर है, और Q के सामने वाला X दक्षिणी पंक्ति की सीट 4 पर। X के ठीक बाएँ Y सीट 3 पर है, और R के सामने Z सीट 2 पर, जिससे W सीट 1 पर बचता है। S, Y के सामने नहीं हो सकता, इसलिए S सीट 1 और P सीट 3 लेता है, Y के सामने। W, S के सामने है, X, Q के सामने और Z, R के सामने। उत्तरी पंक्ति के लिए ''दायाँ'' पूर्व मानने से Q ग़लत छोर पर पहुँच जाता है।','csat-l2-t03-lr-sa-two-rows-facing','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','How many pairs of positive integers (x, y) satisfy x² - y² = 45?','धनात्मक पूर्णांकों के कितने युग्म (x, y) समीकरण x² - y² = 45 को संतुष्ट करते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "b", "body": "3", "body_hi": "3", "isCorrect": true}, {"id": "c", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "d", "body": "12", "body_hi": "12", "isCorrect": false}]'::jsonb,2.5,0.83,'x² - y² = (x - y)(x + y) = 45, where x + y is larger than x - y and both are positive. The factor pairs of 45 are 1 × 45, 3 × 15 and 5 × 9, giving (x, y) = (23, 22), (9, 6) and (7, 2): three pairs. 6 counts each of the six divisors of 45 as if it gave a pair, including the orders in which x - y would exceed x + y; 12 also lets x and y be negative; 2 misses the pair that comes from 1 × 45.','x² - y² = (x - y)(x + y) = 45, जहाँ x + y, x - y से बड़ा है और दोनों धनात्मक हैं। 45 के गुणनखंड-युग्म 1 × 45, 3 × 15 और 5 × 9 हैं, जिनसे (x, y) = (23, 22), (9, 6) और (7, 2) मिलते हैं: तीन युग्म। 6, 45 के छहों भाजकों को ऐसे गिनता है मानो हर एक से एक युग्म बनता हो, उन क्रमों सहित जिनमें x - y, x + y से बड़ा हो जाता; 12, x और y को ऋणात्मक भी होने देता है; 2, 1 × 45 से बनने वाला युग्म छोड़ देता है।','csat-l2-t03-qa-nt-difference-of-squares-45','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Best Summary','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When offices emptied during the pandemic, many predicted the end of the big city: if work could be done from anywhere, why pay city rents? The prediction has not come true, but something has shifted. Jobs that can be done at a screen are now less tied to a place, and some workers have moved to smaller towns, taking city salaries with them. Yet the work that most city residents do -- cooking, cleaning, building, caring, selling -- cannot be done remotely at all. And even screen workers gather in cities for what remote work handles badly: learning from colleagues, chance meetings, a variety of jobs to move between. Cities are unlikely to empty; what is likelier is that they will have to compete harder for the workers who could live anywhere.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
महामारी के दौरान जब दफ़्तर ख़ाली हुए, तो बहुतों ने बड़े शहर के अंत की भविष्यवाणी की: यदि काम कहीं से भी हो सकता है, तो शहर का किराया क्यों दें? यह भविष्यवाणी सच नहीं हुई, पर कुछ बदला ज़रूर है। जो काम स्क्रीन पर हो सकते हैं, वे अब किसी स्थान से कम बँधे हैं, और कुछ कर्मचारी शहर का वेतन साथ लेकर छोटे कस्बों में चले गए हैं। फिर भी शहर के अधिकांश निवासी जो काम करते हैं -- खाना बनाना, सफ़ाई, निर्माण, देखभाल, बिक्री -- वह दूर से हो ही नहीं सकता। और स्क्रीन पर काम करने वाले भी उन चीज़ों के लिए शहरों में जुटते हैं जिन्हें दूर से काम ठीक से नहीं सँभाल पाता: सहकर्मियों से सीखना, संयोग से होने वाली मुलाक़ातें, बदलने के लिए नौकरियों की विविधता। शहरों के ख़ाली होने की संभावना कम है; अधिक संभावना यह है कि उन्हें उन कर्मचारियों के लिए कड़ी होड़ करनी होगी जो कहीं भी रह सकते हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p02", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "Remote work frees some workers from cities, which will survive but must compete for them.", "body_hi": "दूर से काम कुछ कर्मचारियों को शहरों से छुड़ाता है; शहर बचेंगे, पर उनके लिए होड़ करेंगे।", "isCorrect": true}, {"id": "b", "body": "Big cities will empty out as more and more work moves online and offices close down.", "body_hi": "जैसे-जैसे अधिक काम ऑनलाइन होगा और दफ़्तर बंद होंगे, बड़े शहर ख़ाली हो जाएँगे।", "isCorrect": false}, {"id": "c", "body": "Most people who live in cities now do their work from home instead of at an office.", "body_hi": "शहरों में रहने वाले अधिकांश लोग अब दफ़्तर के बजाय घर से काम करते हैं।", "isCorrect": false}, {"id": "d", "body": "Small towns pay better salaries than big cities, which is why workers are moving to them.", "body_hi": "छोटे कस्बे बड़े शहरों की तुलना में अधिक वेतन देते हैं, और इसीलिए कर्मचारी उनकी ओर जा रहे हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says the predicted emptying of cities has not happened, that most city work cannot be done remotely, and that cities will have to compete for the workers who could live anywhere. Emptying cities is the prediction it rejects; most city residents cannot work from home at all; and the passage says workers took city salaries to the towns, not that towns pay more.','परिच्छेद कहता है कि शहरों के ख़ाली होने की भविष्यवाणी सच नहीं हुई, कि शहर का अधिकांश काम दूर से नहीं हो सकता, और कि शहरों को उन कर्मचारियों के लिए होड़ करनी होगी जो कहीं भी रह सकते हैं। शहरों का ख़ाली होना वही भविष्यवाणी है जिसे वह नकारता है; शहर के अधिकांश निवासी घर से काम कर ही नहीं सकते; और परिच्छेद कहता है कि कर्मचारी शहर का वेतन कस्बों में ले गए, यह नहीं कि कस्बे अधिक वेतन देते हैं।','csat-l2-t03-rc-p02-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When offices emptied during the pandemic, many predicted the end of the big city: if work could be done from anywhere, why pay city rents? The prediction has not come true, but something has shifted. Jobs that can be done at a screen are now less tied to a place, and some workers have moved to smaller towns, taking city salaries with them. Yet the work that most city residents do -- cooking, cleaning, building, caring, selling -- cannot be done remotely at all. And even screen workers gather in cities for what remote work handles badly: learning from colleagues, chance meetings, a variety of jobs to move between. Cities are unlikely to empty; what is likelier is that they will have to compete harder for the workers who could live anywhere.

According to the passage, which one of the following does remote work handle badly?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
महामारी के दौरान जब दफ़्तर ख़ाली हुए, तो बहुतों ने बड़े शहर के अंत की भविष्यवाणी की: यदि काम कहीं से भी हो सकता है, तो शहर का किराया क्यों दें? यह भविष्यवाणी सच नहीं हुई, पर कुछ बदला ज़रूर है। जो काम स्क्रीन पर हो सकते हैं, वे अब किसी स्थान से कम बँधे हैं, और कुछ कर्मचारी शहर का वेतन साथ लेकर छोटे कस्बों में चले गए हैं। फिर भी शहर के अधिकांश निवासी जो काम करते हैं -- खाना बनाना, सफ़ाई, निर्माण, देखभाल, बिक्री -- वह दूर से हो ही नहीं सकता। और स्क्रीन पर काम करने वाले भी उन चीज़ों के लिए शहरों में जुटते हैं जिन्हें दूर से काम ठीक से नहीं सँभाल पाता: सहकर्मियों से सीखना, संयोग से होने वाली मुलाक़ातें, बदलने के लिए नौकरियों की विविधता। शहरों के ख़ाली होने की संभावना कम है; अधिक संभावना यह है कि उन्हें उन कर्मचारियों के लिए कड़ी होड़ करनी होगी जो कहीं भी रह सकते हैं।

परिच्छेद के अनुसार, दूर से काम निम्नलिखित में से किसे ठीक से नहीं सँभाल पाता?','{"craft": "precision", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p02", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "earning a city salary", "body_hi": "शहर जैसा वेतन कमाना", "isCorrect": false}, {"id": "b", "body": "reaching the office on time", "body_hi": "समय पर दफ़्तर पहुँचना", "isCorrect": false}, {"id": "c", "body": "learning from colleagues", "body_hi": "सहकर्मियों से सीखना", "isCorrect": true}, {"id": "d", "body": "finding a cheaper home", "body_hi": "सस्ता घर ढूँढ पाना", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage lists what remote work handles badly: learning from colleagues, chance meetings and a variety of jobs to move between. Earning a city salary is something remote work allows -- workers took city salaries with them to the towns; reaching the office on time and finding a cheaper home are not given as things remote work handles badly.','परिच्छेद गिनाता है कि दूर से काम किसे ठीक से नहीं सँभाल पाता: सहकर्मियों से सीखना, संयोग से होने वाली मुलाक़ातें और बदलने के लिए नौकरियों की विविधता। शहर जैसा वेतन कमाना तो दूर से काम संभव बनाता है -- कर्मचारी शहर का वेतन कस्बों में साथ ले गए; समय पर दफ़्तर पहुँचना और सस्ता घर ढूँढना ऐसी बातों के रूप में नहीं दिए गए जिन्हें दूर से काम ठीक से नहीं सँभालता।','csat-l2-t03-rc-p02-detail','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When offices emptied during the pandemic, many predicted the end of the big city: if work could be done from anywhere, why pay city rents? The prediction has not come true, but something has shifted. Jobs that can be done at a screen are now less tied to a place, and some workers have moved to smaller towns, taking city salaries with them. Yet the work that most city residents do -- cooking, cleaning, building, caring, selling -- cannot be done remotely at all. And even screen workers gather in cities for what remote work handles badly: learning from colleagues, chance meetings, a variety of jobs to move between. Cities are unlikely to empty; what is likelier is that they will have to compete harder for the workers who could live anywhere.

Which of the following inferences can be drawn from the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
महामारी के दौरान जब दफ़्तर ख़ाली हुए, तो बहुतों ने बड़े शहर के अंत की भविष्यवाणी की: यदि काम कहीं से भी हो सकता है, तो शहर का किराया क्यों दें? यह भविष्यवाणी सच नहीं हुई, पर कुछ बदला ज़रूर है। जो काम स्क्रीन पर हो सकते हैं, वे अब किसी स्थान से कम बँधे हैं, और कुछ कर्मचारी शहर का वेतन साथ लेकर छोटे कस्बों में चले गए हैं। फिर भी शहर के अधिकांश निवासी जो काम करते हैं -- खाना बनाना, सफ़ाई, निर्माण, देखभाल, बिक्री -- वह दूर से हो ही नहीं सकता। और स्क्रीन पर काम करने वाले भी उन चीज़ों के लिए शहरों में जुटते हैं जिन्हें दूर से काम ठीक से नहीं सँभाल पाता: सहकर्मियों से सीखना, संयोग से होने वाली मुलाक़ातें, बदलने के लिए नौकरियों की विविधता। शहरों के ख़ाली होने की संभावना कम है; अधिक संभावना यह है कि उन्हें उन कर्मचारियों के लिए कड़ी होड़ करनी होगी जो कहीं भी रह सकते हैं।

परिच्छेद से निम्नलिखित में से कौन-से अनुमान निकाले जा सकते हैं?','{"statements": ["Most city residents could not keep their present jobs if they moved to a small town.", "A city that offers a good life may draw workers who could live anywhere.", "Remote work has lowered rents in every big city."], "statements_hi": ["शहर के अधिकांश निवासी छोटे कस्बे में चले जाने पर अपनी वर्तमान नौकरी नहीं रख सकते।", "जो शहर अच्छा जीवन देता है, वह उन कर्मचारियों को खींच सकता है जो कहीं भी रह सकते हैं।", "दूर से काम ने हर बड़े शहर में किराये घटा दिए हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}, {"id": "c", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}, {"id": "d", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": true}]'::jsonb,2.5,0.83,'1 and 2 follow. The work most city residents do ''cannot be done remotely at all'', so they could not keep their present jobs from a small town (1). Cities having to ''compete harder'' for the workers who could live anywhere implies that what a city offers can draw such workers (2). 3 goes beyond the passage, which says nothing about rents falling.','1 और 2 निकलते हैं। शहर के अधिकांश निवासी जो काम करते हैं वह ''दूर से हो ही नहीं सकता'', इसलिए वे छोटे कस्बे से अपनी वर्तमान नौकरी नहीं रख सकते (1)। शहरों को उन कर्मचारियों के लिए ''कड़ी होड़'' करनी होगी जो कहीं भी रह सकते हैं, जिसका अर्थ है कि शहर जो देता है वह ऐसे कर्मचारियों को खींच सकता है (2)। 3 परिच्छेद से आगे जाता है, जो किराये घटने के बारे में कुछ नहीं कहता।','csat-l2-t03-rc-p02-inferences','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','medium','In a geometric progression the 3rd term is 24 and the 6th term is 192. What is the 10th term?','एक गुणोत्तर श्रेणी का तीसरा पद 24 और छठा पद 192 है। उसका दसवाँ पद क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "1536", "body_hi": "1536", "isCorrect": false}, {"id": "b", "body": "3072", "body_hi": "3072", "isCorrect": true}, {"id": "c", "body": "6144", "body_hi": "6144", "isCorrect": false}, {"id": "d", "body": "12288", "body_hi": "12288", "isCorrect": false}]'::jsonb,2.5,0.83,'From the 3rd term to the 6th the common ratio is applied three times: r³ = 192/24 = 8, so r = 2, and the first term is 24/2² = 6. The 10th term is 6 × 2⁹ = 3072. 1536 and 6144 are the 9th and 11th terms, from counting the powers of 2 one short or one over; 12288 is the 12th.','तीसरे पद से छठे पद तक सार्व अनुपात तीन बार लगता है: r³ = 192/24 = 8, अतः r = 2, और पहला पद 24/2² = 6 है। दसवाँ पद 6 × 2⁹ = 3072 है। 1536 और 6144 नौवें और ग्यारहवें पद हैं, जो 2 की घातें एक कम या एक अधिक गिनने से आते हैं; 12288 बारहवाँ पद है।','csat-l2-t03-qa-ss-gp-from-third-and-sixth','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','A town''s streets form a grid of square blocks, 4 blocks from west to east and 3 blocks from south to north. Walking only east or north along the streets, in how many different ways can a person go from the south-west corner of the grid to its north-east corner?','एक कस्बे की सड़कें वर्गाकार खंडों का एक जाल बनाती हैं, पश्चिम से पूर्व 4 खंड और दक्षिण से उत्तर 3 खंड। सड़कों पर केवल पूर्व या उत्तर की ओर चलते हुए कोई व्यक्ति जाल के दक्षिण-पश्चिमी कोने से उत्तर-पूर्वी कोने तक कितने अलग-अलग तरीकों से जा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "35", "body_hi": "35", "isCorrect": true}, {"id": "b", "body": "70", "body_hi": "70", "isCorrect": false}, {"id": "c", "body": "128", "body_hi": "128", "isCorrect": false}, {"id": "d", "body": "5040", "body_hi": "5040", "isCorrect": false}]'::jsonb,2.5,0.83,'Every such route has 7 moves, 4 of them east and 3 north, and a route is fixed by choosing which 3 of the 7 moves go north: C(7, 3) = 35. 128 = 2⁷ lets each move go either way, ignoring that exactly 4 must go east; 5040 = 7! treats the 7 moves as all different; 70 = C(8, 4) is the count for a grid 4 blocks by 4.','हर ऐसे रास्ते में 7 चालें हैं, 4 पूर्व की ओर और 3 उत्तर की ओर, और रास्ता यह चुनने से तय होता है कि 7 में से कौन-सी 3 चालें उत्तर की ओर हों: C(7, 3) = 35। 128 = 2⁷ हर चाल को किसी भी ओर जाने देता है, यह भूलकर कि ठीक 4 पूर्व की ओर होनी चाहिए; 5040 = 7! सातों चालों को अलग-अलग मानता है; 70 = C(8, 4), 4 × 4 खंडों वाले जाल की गिनती है।','csat-l2-t03-qa-pc-grid-routes-4-by-3','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','easy','A is the brother of B. B is the daughter of C, and C is the only son of D. How is A related to D?','A, B का भाई है। B, C की बेटी है, और C, D का इकलौता बेटा है। A, D का क्या लगता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "Son", "body_hi": "पुत्र", "isCorrect": false}, {"id": "b", "body": "Nephew", "body_hi": "भतीजा", "isCorrect": false}, {"id": "c", "body": "Son-in-law", "body_hi": "दामाद", "isCorrect": false}, {"id": "d", "body": "Grandson", "body_hi": "पोता", "isCorrect": true}]'::jsonb,2.5,0.83,'C is D''s son and B is C''s daughter, so B is D''s granddaughter; A, B''s brother, is C''s son and so D''s grandson (पोता, through D''s son). ''Son'' stops a generation short, at C; a nephew would need A''s parent to be D''s brother or sister; a son-in-law would be married to D''s daughter.','C, D का बेटा है और B, C की बेटी, इसलिए B, D की पोती है; B का भाई A, C का बेटा है और इसलिए D का पोता (D के बेटे के माध्यम से)। ''पुत्र'' एक पीढ़ी पहले, C पर, रुक जाता है; भतीजा होने के लिए A के माता-पिता में से कोई D का भाई या बहन होना चाहिए; दामाद D की बेटी का पति होता।','csat-l2-t03-lr-br-only-son-of-d','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','A ladder 25 m long leans against a vertical wall with its top 24 m above the ground. If the top slides 4 m down the wall, how far does the foot of the ladder move away from the wall?','25 मीटर लंबी एक सीढ़ी एक ऊर्ध्वाधर दीवार से इस प्रकार टिकी है कि उसका ऊपरी सिरा ज़मीन से 24 मीटर ऊँचा है। यदि ऊपरी सिरा दीवार पर 4 मीटर नीचे खिसक जाए, तो सीढ़ी का निचला सिरा दीवार से कितना और दूर खिसकेगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "4 m", "body_hi": "4 मीटर", "isCorrect": false}, {"id": "b", "body": "8 m", "body_hi": "8 मीटर", "isCorrect": true}, {"id": "c", "body": "15 m", "body_hi": "15 मीटर", "isCorrect": false}, {"id": "d", "body": "20 m", "body_hi": "20 मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'At first the foot is √(25² - 24²) = √49 = 7 m from the wall. With the top at 20 m, the foot is √(25² - 20²) = √225 = 15 m away, so it has moved 15 - 7 = 8 m. 4 m assumes the foot moves as far as the top; 15 m is the foot''s new distance from the wall, not the change; 20 m is the new height of the top.','शुरू में निचला सिरा दीवार से √(25² - 24²) = √49 = 7 मीटर दूर है। ऊपरी सिरा 20 मीटर पर होने पर निचला सिरा √(25² - 20²) = √225 = 15 मीटर दूर है, अतः वह 15 - 7 = 8 मीटर खिसका है। 4 मीटर मान लेता है कि निचला सिरा उतना ही खिसकता है जितना ऊपरी; 15 मीटर दीवार से निचले सिरे की नई दूरी है, बदलाव नहीं; 20 मीटर ऊपरी सिरे की नई ऊँचाई है।','csat-l2-t03-qa-gm-ladder-slides-down','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Small loans to poor women, repaid in weekly instalments within groups, were once hailed as a way out of poverty. The record is more modest. Studies that compared villages with and without such lenders found that the loans helped households even out their spending, buy assets and cope with emergencies, but rarely transformed their incomes. The danger lies in success itself. Where many lenders crowd into the same area, a borrower can take a second loan to repay the first, and debts can grow faster than earnings; the weekly meetings that once built discipline then become a source of pressure. A loan is a tool, not a cure. Its value depends on what the borrower can do with it, and on lenders checking how much she already owes.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
ग़रीब महिलाओं को समूहों में दिए गए और साप्ताहिक किस्तों में चुकाए जाने वाले छोटे ऋणों को कभी ग़रीबी से निकलने का रास्ता कहा गया था। उनका रिकॉर्ड अधिक साधारण है। जिन अध्ययनों ने ऐसे ऋणदाताओं वाले और बिना ऋणदाताओं वाले गाँवों की तुलना की, उन्होंने पाया कि ऋणों ने परिवारों को अपना ख़र्च बराबर रखने, संपत्ति ख़रीदने और आपात स्थितियों से निपटने में मदद की, पर उनकी आय को शायद ही कभी बदला। ख़तरा सफलता में ही छिपा है। जहाँ एक ही क्षेत्र में बहुत-से ऋणदाता आ जुटते हैं, वहाँ उधार लेने वाली पहला ऋण चुकाने के लिए दूसरा ऋण ले सकती है, और कर्ज़ कमाई से तेज़ बढ़ सकता है; जो साप्ताहिक बैठकें कभी अनुशासन बनाती थीं, वे तब दबाव का स्रोत बन जाती हैं। ऋण एक औज़ार है, इलाज नहीं। उसका मूल्य इस पर निर्भर करता है कि उधार लेने वाली उससे क्या कर सकती है, और इस पर कि ऋणदाता जाँचें कि वह पहले से कितनी देनदार है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p03", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "Small loans have lifted most of the women who borrowed them out of poverty for good.", "body_hi": "छोटे ऋणों ने उधार लेने वाली अधिकांश महिलाओं को सदा के लिए ग़रीबी से बाहर निकाल दिया है।", "isCorrect": false}, {"id": "b", "body": "Poor women should not be given loans at all, because they cannot repay them.", "body_hi": "ग़रीब महिलाओं को ऋण दिए ही नहीं जाने चाहिए, क्योंकि वे उन्हें चुका नहीं सकतीं।", "isCorrect": false}, {"id": "c", "body": "The weekly meetings of borrowers are the main cause of debt in the villages.", "body_hi": "उधार लेने वालों की साप्ताहिक बैठकें ही गाँवों में कर्ज़ का मुख्य कारण हैं।", "isCorrect": false}, {"id": "d", "body": "Small loans help the poor manage money but can harm them when lenders are careless.", "body_hi": "छोटे ऋण पैसा सँभालने में मदद करते हैं, पर लापरवाही से दिए जाएँ तो हानि कर सकते हैं।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage scales down the claim that small loans end poverty -- they help households manage -- and warns that crowded, careless lending can trap borrowers in debt. It says the loans ''rarely transformed'' incomes, so they did not lift most borrowers out of poverty; it never says the poor should not borrow; and it treats the weekly meetings as a source of pressure only where lending is crowded, not as the main cause of debt.','परिच्छेद इस दावे को छोटा करता है कि छोटे ऋण ग़रीबी समाप्त करते हैं -- वे परिवारों को सँभलने में मदद करते हैं -- और चेताता है कि भीड़ भरा, लापरवाह ऋण उधार लेने वालों को कर्ज़ में फँसा सकता है। वह कहता है कि ऋणों ने आय को ''शायद ही कभी बदला'', इसलिए उन्होंने अधिकांश उधार लेने वालों को ग़रीबी से नहीं निकाला; वह कहीं नहीं कहता कि ग़रीबों को उधार नहीं लेना चाहिए; और वह साप्ताहिक बैठकों को दबाव का स्रोत केवल वहाँ मानता है जहाँ ऋणदाताओं की भीड़ हो, कर्ज़ का मुख्य कारण नहीं।','csat-l2-t03-rc-p03-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Small loans to poor women, repaid in weekly instalments within groups, were once hailed as a way out of poverty. The record is more modest. Studies that compared villages with and without such lenders found that the loans helped households even out their spending, buy assets and cope with emergencies, but rarely transformed their incomes. The danger lies in success itself. Where many lenders crowd into the same area, a borrower can take a second loan to repay the first, and debts can grow faster than earnings; the weekly meetings that once built discipline then become a source of pressure. A loan is a tool, not a cure. Its value depends on what the borrower can do with it, and on lenders checking how much she already owes.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
ग़रीब महिलाओं को समूहों में दिए गए और साप्ताहिक किस्तों में चुकाए जाने वाले छोटे ऋणों को कभी ग़रीबी से निकलने का रास्ता कहा गया था। उनका रिकॉर्ड अधिक साधारण है। जिन अध्ययनों ने ऐसे ऋणदाताओं वाले और बिना ऋणदाताओं वाले गाँवों की तुलना की, उन्होंने पाया कि ऋणों ने परिवारों को अपना ख़र्च बराबर रखने, संपत्ति ख़रीदने और आपात स्थितियों से निपटने में मदद की, पर उनकी आय को शायद ही कभी बदला। ख़तरा सफलता में ही छिपा है। जहाँ एक ही क्षेत्र में बहुत-से ऋणदाता आ जुटते हैं, वहाँ उधार लेने वाली पहला ऋण चुकाने के लिए दूसरा ऋण ले सकती है, और कर्ज़ कमाई से तेज़ बढ़ सकता है; जो साप्ताहिक बैठकें कभी अनुशासन बनाती थीं, वे तब दबाव का स्रोत बन जाती हैं। ऋण एक औज़ार है, इलाज नहीं। उसका मूल्य इस पर निर्भर करता है कि उधार लेने वाली उससे क्या कर सकती है, और इस पर कि ऋणदाता जाँचें कि वह पहले से कितनी देनदार है।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["Borrowers always use their loans for purposes that raise their incomes.", "Lenders are able to find out how much a borrower already owes."], "statements_hi": ["उधार लेने वाले अपने ऋणों का उपयोग सदा ऐसे कामों में करते हैं जिनसे उनकी आय बढ़े।", "ऋणदाता यह पता लगा सकते हैं कि उधार लेने वाला पहले से कितना देनदार है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p03", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is assumed. The remedy the passage proposes -- lenders checking how much a borrower already owes -- works only if lenders are able to find that out. 1 is not assumed and runs against the passage, which says the loans rarely transformed incomes.','केवल 2 पूर्वधारणा है। परिच्छेद जो उपाय सुझाता है -- ऋणदाता जाँचें कि उधार लेने वाली पहले से कितनी देनदार है -- वह तभी काम करता है जब ऋणदाता यह पता लगा सकें। 1 पूर्वधारणा नहीं है और परिच्छेद के विरुद्ध जाता है, जो कहता है कि ऋणों ने आय को शायद ही कभी बदला।','csat-l2-t03-rc-p03-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Small loans to poor women, repaid in weekly instalments within groups, were once hailed as a way out of poverty. The record is more modest. Studies that compared villages with and without such lenders found that the loans helped households even out their spending, buy assets and cope with emergencies, but rarely transformed their incomes. The danger lies in success itself. Where many lenders crowd into the same area, a borrower can take a second loan to repay the first, and debts can grow faster than earnings; the weekly meetings that once built discipline then become a source of pressure. A loan is a tool, not a cure. Its value depends on what the borrower can do with it, and on lenders checking how much she already owes.

Which of the following inferences can be drawn from the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
ग़रीब महिलाओं को समूहों में दिए गए और साप्ताहिक किस्तों में चुकाए जाने वाले छोटे ऋणों को कभी ग़रीबी से निकलने का रास्ता कहा गया था। उनका रिकॉर्ड अधिक साधारण है। जिन अध्ययनों ने ऐसे ऋणदाताओं वाले और बिना ऋणदाताओं वाले गाँवों की तुलना की, उन्होंने पाया कि ऋणों ने परिवारों को अपना ख़र्च बराबर रखने, संपत्ति ख़रीदने और आपात स्थितियों से निपटने में मदद की, पर उनकी आय को शायद ही कभी बदला। ख़तरा सफलता में ही छिपा है। जहाँ एक ही क्षेत्र में बहुत-से ऋणदाता आ जुटते हैं, वहाँ उधार लेने वाली पहला ऋण चुकाने के लिए दूसरा ऋण ले सकती है, और कर्ज़ कमाई से तेज़ बढ़ सकता है; जो साप्ताहिक बैठकें कभी अनुशासन बनाती थीं, वे तब दबाव का स्रोत बन जाती हैं। ऋण एक औज़ार है, इलाज नहीं। उसका मूल्य इस पर निर्भर करता है कि उधार लेने वाली उससे क्या कर सकती है, और इस पर कि ऋणदाता जाँचें कि वह पहले से कितनी देनदार है।

परिच्छेद से निम्नलिखित में से कौन-से अनुमान निकाले जा सकते हैं?','{"statements": ["Small loans have done more to help households manage money than to raise their incomes.", "Competition among lenders in one area can leave borrowers worse off.", "The weekly group meetings have never been of any use to borrowers."], "statements_hi": ["छोटे ऋणों ने परिवारों की आय बढ़ाने से अधिक उन्हें पैसा सँभालने में मदद की है।", "एक क्षेत्र में ऋणदाताओं की होड़ उधार लेने वालों की स्थिति बिगाड़ सकती है।", "साप्ताहिक समूह बैठकें उधार लेने वालों के कभी किसी काम की नहीं रहीं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb,2.5,0.83,'1 and 2 follow. The loans helped households even out their spending and cope with emergencies but ''rarely transformed their incomes'' (1). Where many lenders crowd into one area, borrowers take new loans to repay old ones and debts outgrow earnings (2). 3 contradicts the passage: the meetings ''once built discipline''.','1 और 2 निकलते हैं। ऋणों ने परिवारों को ख़र्च बराबर रखने और आपात स्थितियों से निपटने में मदद की, पर ''उनकी आय को शायद ही कभी बदला'' (1)। जहाँ एक क्षेत्र में बहुत-से ऋणदाता जुटते हैं, वहाँ उधार लेने वाले पुराने ऋण चुकाने के लिए नए ऋण लेते हैं और कर्ज़ कमाई से आगे निकल जाता है (2)। 3 परिच्छेद का खंडन करता है: बैठकें ''कभी अनुशासन बनाती थीं''।','csat-l2-t03-rc-p03-inferences','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','medium','A man is facing north. He turns 135° clockwise, then 270° anticlockwise, and then 45° clockwise. In which direction is he facing now?','एक व्यक्ति उत्तर की ओर मुँह करके खड़ा है। वह 135° दक्षिणावर्त घूमता है, फिर 270° वामावर्त, और फिर 45° दक्षिणावर्त। अब उसका मुँह किस दिशा में है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "East", "body_hi": "पूर्व", "isCorrect": false}, {"id": "b", "body": "South", "body_hi": "दक्षिण", "isCorrect": false}, {"id": "c", "body": "South-west", "body_hi": "दक्षिण-पश्चिम", "isCorrect": false}, {"id": "d", "body": "West", "body_hi": "पश्चिम", "isCorrect": true}]'::jsonb,2.5,0.83,'Measure clockwise from north: 0 + 135 = 135° (south-east); 135 - 270 = -135°, which is 225° (south-west); 225 + 45 = 270°, which is west. East comes from making the 270° turn clockwise; south-west stops before the last turn; south makes the last 45° turn anticlockwise.','उत्तर से दक्षिणावर्त मापिए: 0 + 135 = 135° (दक्षिण-पूर्व); 135 - 270 = -135°, यानी 225° (दक्षिण-पश्चिम); 225 + 45 = 270°, यानी पश्चिम। पूर्व तब आता है जब 270° का मोड़ दक्षिणावर्त लिया जाए; दक्षिण-पश्चिम अंतिम मोड़ से पहले रुक जाता है; दक्षिण अंतिम 45° का मोड़ वामावर्त ले लेता है।','csat-l2-t03-lr-dd-turns-by-angles','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','medium','12 men or 18 women can finish a piece of work in 14 days. In how many days will 8 men and 16 women together finish it?','12 पुरुष या 18 महिलाएँ एक काम को 14 दिनों में पूरा कर सकते हैं। 8 पुरुष और 16 महिलाएँ मिलकर उसे कितने दिनों में पूरा करेंगे?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "7", "body_hi": "7", "isCorrect": false}, {"id": "b", "body": "9", "body_hi": "9", "isCorrect": true}, {"id": "c", "body": "10.5", "body_hi": "10.5", "isCorrect": false}, {"id": "d", "body": "14", "body_hi": "14", "isCorrect": false}]'::jsonb,2.5,0.83,'12 men do as much as 18 women, so 1 man = 1.5 women and 8 men = 12 women; 8 men and 16 women are thus worth 28 women. The work is 18 × 14 = 252 woman-days, so 28 women need 252 ÷ 28 = 9 days. 7 treats every woman as a man (24 men for 168 man-days); 10.5 treats every man as a woman (24 women for 252 woman-days); 14 is the original time.','12 पुरुष उतना काम करते हैं जितना 18 महिलाएँ, इसलिए 1 पुरुष = 1.5 महिला और 8 पुरुष = 12 महिलाएँ; अतः 8 पुरुष और 16 महिलाएँ 28 महिलाओं के बराबर हैं। काम 18 × 14 = 252 महिला-दिन है, इसलिए 28 महिलाओं को 252 ÷ 28 = 9 दिन लगेंगे। 7 हर महिला को पुरुष मान लेता है (168 पुरुष-दिन के लिए 24 पुरुष); 10.5 हर पुरुष को महिला मान लेता है (252 महिला-दिन के लिए 24 महिलाएँ); 14 मूल समय है।','csat-l2-t03-qa-tw-men-and-women-equivalence','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A batsman''s average after 16 innings is 36 runs. How many runs must he score in his 17th innings to raise his average by 2 runs?','16 पारियों के बाद एक बल्लेबाज़ का औसत 36 रन है। अपना औसत 2 रन बढ़ाने के लिए उसे 17वीं पारी में कितने रन बनाने होंगे?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "38", "body_hi": "38", "isCorrect": false}, {"id": "b", "body": "68", "body_hi": "68", "isCorrect": false}, {"id": "c", "body": "70", "body_hi": "70", "isCorrect": true}, {"id": "d", "body": "72", "body_hi": "72", "isCorrect": false}]'::jsonb,2.5,0.83,'After 16 innings he has 16 × 36 = 576 runs; an average of 38 over 17 innings needs 17 × 38 = 646. He must score 646 - 576 = 70: the new average, 38, plus 2 more for each of the 16 earlier innings. 38 is only the new average; 68 adds 2 per earlier innings to the old average instead of the new one; 72 adds 2 for all 17 innings.','16 पारियों के बाद उसके 16 × 36 = 576 रन हैं; 17 पारियों में 38 का औसत चाहिए तो 17 × 38 = 646 रन। उसे 646 - 576 = 70 रन बनाने होंगे: नया औसत 38, और पहले की 16 पारियों में से हर एक के लिए 2 और। 38 केवल नया औसत है; 68 पहले की हर पारी के 2 रन नए के बजाय पुराने औसत में जोड़ता है; 72 सभी 17 पारियों के लिए 2 जोड़ता है।','csat-l2-t03-qa-rm-batting-average-up-by-2','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','medium','In a certain code, GARDEN is written as HZSCFM. How is FLOWER written in that code?','एक निश्चित कूट में GARDEN को HZSCFM लिखा जाता है। उसी कूट में FLOWER को कैसे लिखा जाएगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "EKNVDQ", "body_hi": "EKNVDQ", "isCorrect": false}, {"id": "b", "body": "GKPVFQ", "body_hi": "GKPVFQ", "isCorrect": true}, {"id": "c", "body": "GKPXFQ", "body_hi": "GKPXFQ", "isCorrect": false}, {"id": "d", "body": "GMPXFS", "body_hi": "GMPXFS", "isCorrect": false}]'::jsonb,2.5,0.83,'Compare letter by letter: G → H (+1), A → Z (-1, going round the alphabet), R → S (+1), D → C (-1), E → F (+1), N → M (-1): the letters move one step forward and one step back in turn. FLOWER becomes F + 1 = G, L - 1 = K, O + 1 = P, W - 1 = V, E + 1 = F, R - 1 = Q: GKPVFQ. GMPXFS moves every letter forward; EKNVDQ moves every letter back; GKPXFQ moves the W forward instead of back.','अक्षर-दर-अक्षर तुलना कीजिए: G → H (+1), A → Z (-1, वर्णमाला में घूमकर), R → S (+1), D → C (-1), E → F (+1), N → M (-1): अक्षर बारी-बारी से एक कदम आगे और एक कदम पीछे जाते हैं। FLOWER बनता है F + 1 = G, L - 1 = K, O + 1 = P, W - 1 = V, E + 1 = F, R - 1 = Q: GKPVFQ। GMPXFS हर अक्षर को आगे ले जाता है; EKNVDQ हर अक्षर को पीछे; GKPXFQ, W को पीछे के बजाय आगे ले जाता है।','csat-l2-t03-lr-cd-forward-and-back-in-turn','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
More than ten thousand working satellites now circle the Earth, and with them millions of fragments -- spent rocket stages, dead satellites and the debris of collisions -- moving faster than a bullet. A fragment the size of a coin can disable a satellite, and each collision creates more fragments, so that in a crowded orbit the debris can multiply even if no one launches anything new. No single country can solve this, since debris respects no borders, and the low cost of launching today rewards whoever gets there first. Rules that require satellites to be steered down and burnt up at the end of their working lives exist, but in much of the world they are voluntary.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अब दस हज़ार से अधिक कार्यरत उपग्रह पृथ्वी की परिक्रमा करते हैं, और उनके साथ दसियों लाख टुकड़े -- ख़र्च हो चुके रॉकेट चरण, निष्क्रिय उपग्रह और टक्करों का मलबा -- गोली से भी तेज़ चलते हैं। सिक्के के आकार का एक टुकड़ा किसी उपग्रह को बेकार कर सकता है, और हर टक्कर और टुकड़े बनाती है, जिससे भीड़ भरी कक्षा में मलबा तब भी बढ़ता जा सकता है जब कोई कुछ भी नया प्रक्षेपित न करे। कोई एक देश इसका समाधान नहीं कर सकता, क्योंकि मलबा कोई सीमा नहीं मानता, और आज प्रक्षेपण की कम लागत उसी को पुरस्कृत करती है जो पहले पहुँचे। ऐसे नियम मौजूद हैं जो अपेक्षा करते हैं कि उपग्रहों को उनके कार्यकाल के अंत में नीचे लाकर जला दिया जाए, पर दुनिया के बड़े भाग में वे स्वैच्छिक हैं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Stopping all new launches would not by itself make a crowded orbit safe.", "Debris endangers only the satellites of the country that produced it."], "statements_hi": ["सभी नए प्रक्षेपण रोक देने भर से भीड़ भरी कक्षा सुरक्षित नहीं हो जाएगी।", "मलबा केवल उसी देश के उपग्रहों के लिए ख़तरा है जिसने उसे पैदा किया।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p04", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. Because each collision creates more fragments, debris ''can multiply even if no one launches anything new'', so stopping launches would not on its own make a crowded orbit safe. 2 contradicts the passage: debris ''respects no borders''.','केवल 1 वैध है। चूँकि हर टक्कर और टुकड़े बनाती है, मलबा ''तब भी बढ़ता जा सकता है जब कोई कुछ भी नया प्रक्षेपित न करे'', इसलिए प्रक्षेपण रोक देने भर से भीड़ भरी कक्षा सुरक्षित नहीं हो जाएगी। 2 परिच्छेद का खंडन करता है: मलबा ''कोई सीमा नहीं मानता''।','csat-l2-t03-rc-p04-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
More than ten thousand working satellites now circle the Earth, and with them millions of fragments -- spent rocket stages, dead satellites and the debris of collisions -- moving faster than a bullet. A fragment the size of a coin can disable a satellite, and each collision creates more fragments, so that in a crowded orbit the debris can multiply even if no one launches anything new. No single country can solve this, since debris respects no borders, and the low cost of launching today rewards whoever gets there first. Rules that require satellites to be steered down and burnt up at the end of their working lives exist, but in much of the world they are voluntary.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अब दस हज़ार से अधिक कार्यरत उपग्रह पृथ्वी की परिक्रमा करते हैं, और उनके साथ दसियों लाख टुकड़े -- ख़र्च हो चुके रॉकेट चरण, निष्क्रिय उपग्रह और टक्करों का मलबा -- गोली से भी तेज़ चलते हैं। सिक्के के आकार का एक टुकड़ा किसी उपग्रह को बेकार कर सकता है, और हर टक्कर और टुकड़े बनाती है, जिससे भीड़ भरी कक्षा में मलबा तब भी बढ़ता जा सकता है जब कोई कुछ भी नया प्रक्षेपित न करे। कोई एक देश इसका समाधान नहीं कर सकता, क्योंकि मलबा कोई सीमा नहीं मानता, और आज प्रक्षेपण की कम लागत उसी को पुरस्कृत करती है जो पहले पहुँचे। ऐसे नियम मौजूद हैं जो अपेक्षा करते हैं कि उपग्रहों को उनके कार्यकाल के अंत में नीचे लाकर जला दिया जाए, पर दुनिया के बड़े भाग में वे स्वैच्छिक हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p04", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "Satellites should no longer be launched into the low orbits around the Earth at all.", "body_hi": "पृथ्वी के चारों ओर की निचली कक्षाओं में अब उपग्रह भेजना पूरी तरह बंद कर देना चाहिए।", "isCorrect": false}, {"id": "b", "body": "Only large pieces of debris, such as spent rocket stages, are a danger to satellites.", "body_hi": "केवल बड़े टुकड़े, जैसे ख़र्च हो चुके रॉकेट चरण, ही उपग्रहों के लिए ख़तरा हैं।", "isCorrect": false}, {"id": "c", "body": "Launching a satellite has become too costly for most of the countries of the world.", "body_hi": "उपग्रह प्रक्षेपित करना दुनिया के अधिकांश देशों के लिए बहुत महँगा हो गया है।", "isCorrect": false}, {"id": "d", "body": "Debris is a shared danger that voluntary rules and a race to launch leave unchecked.", "body_hi": "मलबा साझा ख़तरा है, जिसे स्वैच्छिक नियम और प्रक्षेपण की होड़ बेरोक छोड़ देते हैं।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage describes a danger that no single country can solve, made worse by cheap launches that reward whoever comes first and by rules that are only voluntary. It does not call for an end to launches into low orbit; it says even a coin-sized fragment is dangerous; and it says launching is now cheap, not costly.','परिच्छेद एक ऐसे ख़तरे का वर्णन करता है जिसे कोई एक देश हल नहीं कर सकता, और जिसे पहले पहुँचने वाले को पुरस्कृत करने वाले सस्ते प्रक्षेपण और केवल स्वैच्छिक नियम और बढ़ाते हैं। वह निचली कक्षा में प्रक्षेपण बंद करने की माँग नहीं करता; वह कहता है कि सिक्के जितना टुकड़ा भी ख़तरनाक है; और वह कहता है कि प्रक्षेपण अब सस्ता है, महँगा नहीं।','csat-l2-t03-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the smallest positive number that leaves remainders of 4, 6 and 13 when divided by 6, 8 and 15 respectively?','वह सबसे छोटी धनात्मक संख्या कौन-सी है जो 6, 8 और 15 से भाग देने पर क्रमशः 4, 6 और 13 शेषफल छोड़ती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "118", "body_hi": "118", "isCorrect": true}, {"id": "b", "body": "122", "body_hi": "122", "isCorrect": false}, {"id": "c", "body": "238", "body_hi": "238", "isCorrect": false}, {"id": "d", "body": "358", "body_hi": "358", "isCorrect": false}]'::jsonb,2.5,0.83,'Each remainder is 2 less than its divisor (6 - 4 = 8 - 6 = 15 - 13 = 2), so the number plus 2 is divisible by 6, 8 and 15, that is by their LCM, 120. The smallest such number is 120 - 2 = 118. 238 (= 240 - 2) and 358 (= 360 - 2) also leave these remainders but are not the smallest; 122 adds the 2 instead of subtracting it.','हर शेषफल अपने भाजक से 2 कम है (6 - 4 = 8 - 6 = 15 - 13 = 2), इसलिए संख्या में 2 जोड़ने पर वह 6, 8 और 15 से, यानी उनके LCM 120 से, विभाज्य होगी। ऐसी सबसे छोटी संख्या 120 - 2 = 118 है। 238 (= 240 - 2) और 358 (= 360 - 2) भी ये शेषफल छोड़ती हैं पर सबसे छोटी नहीं हैं; 122, 2 घटाने के बजाय जोड़ देता है।','csat-l2-t03-qa-nt-remainders-two-short','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','Two cyclists start at the same time from two towns 60 km apart and ride towards each other at 12 km/h and 18 km/h. At that moment a bird starts from the first cyclist and flies back and forth between them at 40 km/h until they meet. How far does the bird fly in all?','दो साइकिल सवार एक ही समय पर 60 किमी दूर स्थित दो कस्बों से चलते हैं और 12 किमी/घंटा तथा 18 किमी/घंटा की चाल से एक-दूसरे की ओर बढ़ते हैं। उसी क्षण एक पक्षी पहले सवार के पास से उड़ता है और उनके मिलने तक 40 किमी/घंटा की चाल से उनके बीच आगे-पीछे उड़ता रहता है। पक्षी कुल कितनी दूरी उड़ता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "24 km", "body_hi": "24 किमी", "isCorrect": false}, {"id": "b", "body": "36 km", "body_hi": "36 किमी", "isCorrect": false}, {"id": "c", "body": "60 km", "body_hi": "60 किमी", "isCorrect": false}, {"id": "d", "body": "80 km", "body_hi": "80 किमी", "isCorrect": true}]'::jsonb,2.5,0.83,'There is no need to add up the bird''s zigzags. The cyclists close the gap at 12 + 18 = 30 km/h, so they meet after 60/30 = 2 hours, and the bird, flying all that time at 40 km/h, covers 80 km. 24 km and 36 km are the distances the two cyclists ride in those 2 hours; 60 km is the gap between the towns.','पक्षी के आगे-पीछे के टुकड़ों को जोड़ने की ज़रूरत नहीं। सवार 12 + 18 = 30 किमी/घंटा से दूरी घटाते हैं, इसलिए 60/30 = 2 घंटे में मिलते हैं, और पक्षी पूरे समय 40 किमी/घंटा से उड़कर 80 किमी तय करता है। 24 किमी और 36 किमी वे दूरियाँ हैं जो दोनों सवार उन 2 घंटों में तय करते हैं; 60 किमी कस्बों के बीच की दूरी है।','csat-l2-t03-qa-sdt-bird-between-cyclists','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','Argument: In the two years since a new metro line opened, road accidents in the city have fallen by 20 per cent. The metro has therefore made the city''s roads safer.

Which one of the following, if true, most weakens the argument?','तर्क: एक नई मेट्रो लाइन खुलने के बाद के दो वर्षों में शहर में सड़क दुर्घटनाएँ 20 प्रतिशत घट गई हैं। अतः मेट्रो ने शहर की सड़कों को अधिक सुरक्षित बना दिया है।

निम्नलिखित में से कौन-सा, यदि सत्य हो, तो तर्क को सबसे अधिक कमज़ोर करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "Many people who used to drive to work every day now travel to their offices by the metro.", "body_hi": "जो बहुत-से लोग पहले रोज़ गाड़ी चलाकर काम पर जाते थे, वे अब मेट्रो से अपने दफ़्तर जाते हैं।", "isCorrect": false}, {"id": "b", "body": "The metro line cost more to build than had been planned.", "body_hi": "मेट्रो लाइन बनाने में योजना से अधिक लागत आई।", "isCorrect": false}, {"id": "c", "body": "The city also lowered speed limits and installed junction cameras in those two years.", "body_hi": "शहर ने उन्हीं दो वर्षों में गति सीमा भी घटाई और चौराहों पर कैमरे भी लगाए।", "isCorrect": true}, {"id": "d", "body": "Most of the road accidents in the city take place on weekday evenings after office hours.", "body_hi": "शहर की अधिकांश सड़क दुर्घटनाएँ कार्यदिवसों की शाम को दफ़्तर के समय के बाद होती हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The argument credits the metro with the fall in accidents. The strongest weakener offers another cause for the same fall: lower speed limits and junction cameras in the same period could explain it without the metro. People leaving their cars for the metro actually supports the argument; the metro''s cost, and the hour at which accidents happen, have no bearing on whether the metro caused the fall.','तर्क दुर्घटनाओं में कमी का श्रेय मेट्रो को देता है। सबसे प्रबल कमज़ोर करने वाला कथन उसी कमी का दूसरा कारण देता है: उसी अवधि में घटी गति सीमा और चौराहों के कैमरे मेट्रो के बिना भी इसकी व्याख्या कर सकते हैं। लोगों का गाड़ी छोड़कर मेट्रो अपनाना तो तर्क का समर्थन करता है; मेट्रो की लागत, और दुर्घटनाएँ किस समय होती हैं, इसका इस बात से कोई संबंध नहीं कि कमी मेट्रो के कारण हुई या नहीं।','csat-l2-t03-lr-sc-metro-rival-cause','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','A drawer holds 10 black, 8 white and 6 blue socks, all mixed up. In the dark, what is the smallest number of socks one must take out to be sure of having two black socks?','एक दराज़ में 10 काले, 8 सफ़ेद और 6 नीले मोज़े आपस में मिले हुए हैं। अँधेरे में, दो काले मोज़े निश्चित रूप से पाने के लिए कम से कम कितने मोज़े निकालने होंगे?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 31}'::jsonb,'[{"id": "a", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "b", "body": "14", "body_hi": "14", "isCorrect": false}, {"id": "c", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "d", "body": "16", "body_hi": "16", "isCorrect": true}]'::jsonb,2.5,0.83,'Plan for the worst luck: all 8 white and all 6 blue socks could come out first, 14 socks with no black one among them. The next two are then certain to be black, so 16 socks are needed. 4 is enough for a pair of the same colour, not for a black pair; 14 might still contain no black sock at all; 15 makes sure of only one black sock.','सबसे बुरी स्थिति मानिए: पहले सभी 8 सफ़ेद और सभी 6 नीले मोज़े निकल सकते हैं, 14 मोज़े जिनमें एक भी काला नहीं। उसके बाद के दो मोज़े निश्चित रूप से काले होंगे, अतः 16 मोज़े चाहिए। 4 एक ही रंग की जोड़ी के लिए पर्याप्त है, काली जोड़ी के लिए नहीं; 14 में अब भी एक भी काला मोज़ा न हो, ऐसा हो सकता है; 15 केवल एक काला मोज़ा निश्चित करता है।','csat-l2-t03-qa-ph-two-black-socks-in-the-dark','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
A civil servant in a democracy serves governments of every party in turn, and the system depends on her serving each of them with the same care. Neutrality does not mean having no views; it means giving honest advice in private and carrying out lawful decisions in public, even those she argued against. It also means knowing where the line lies. An order to bend a rule for a favoured contractor is not a decision to be loyally carried out but one to be refused, and the refusal recorded. Officials who confuse loyalty to the government of the day with loyalty to a minister''s wishes serve neither the public nor the minister: a policy that no one dared to question is a policy that no one has tested.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
लोकतंत्र में एक सिविल सेवक बारी-बारी से हर दल की सरकारों की सेवा करती है, और व्यवस्था इस पर टिकी है कि वह हर एक की सेवा समान निष्ठा से करे। तटस्थता का अर्थ कोई राय न होना नहीं है; इसका अर्थ है निजी रूप से ईमानदार सलाह देना और सार्वजनिक रूप से वैध निर्णयों को लागू करना, उन निर्णयों को भी जिनके विरुद्ध उसने तर्क दिया था। इसका अर्थ यह जानना भी है कि रेखा कहाँ है। किसी चहेते ठेकेदार के लिए नियम मोड़ने का आदेश निष्ठा से लागू करने वाला निर्णय नहीं, बल्कि ठुकराने वाला आदेश है, और ठुकराने को लिखित में दर्ज किया जाना चाहिए। जो अधिकारी तत्कालीन सरकार के प्रति निष्ठा को किसी मंत्री की इच्छाओं के प्रति निष्ठा समझ बैठते हैं, वे न जनता का भला करते हैं न मंत्री का: जिस नीति पर किसी ने प्रश्न उठाने का साहस नहीं किया, उसे किसी ने परखा ही नहीं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p05", "csat_order": 32}'::jsonb,'[{"id": "a", "body": "Neutrality means candid advice, loyal implementation and the refusal of unlawful orders.", "body_hi": "तटस्थता का अर्थ है खरी सलाह, निष्ठापूर्ण अमल और अवैध आदेशों को ठुकराना।", "isCorrect": true}, {"id": "b", "body": "Civil servants should keep their views to themselves and never argue with a minister.", "body_hi": "सिविल सेवकों को अपनी राय अपने तक रखनी चाहिए और मंत्री से कभी बहस नहीं करनी चाहिए।", "isCorrect": false}, {"id": "c", "body": "Civil servants must carry out every order of the minister, since the minister is elected.", "body_hi": "सिविल सेवकों को मंत्री का हर आदेश लागू करना चाहिए, क्योंकि मंत्री निर्वाचित होता है।", "isCorrect": false}, {"id": "d", "body": "Ministers should not question the advice that they receive from their civil servants.", "body_hi": "मंत्रियों को अपने सिविल सेवकों से मिलने वाली सलाह पर प्रश्न नहीं उठाना चाहिए।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage defines neutrality by three duties: honest advice in private, faithful implementation of lawful decisions, and refusal of unlawful orders. It says neutrality ''does not mean having no views'', so keeping quiet is wrong; it says some orders must be refused, so ''every order'' is wrong; and it says nothing about ministers questioning their officials'' advice.','परिच्छेद तटस्थता को तीन कर्तव्यों से परिभाषित करता है: निजी रूप से ईमानदार सलाह, वैध निर्णयों को निष्ठा से लागू करना, और अवैध आदेशों को ठुकराना। वह कहता है कि तटस्थता का ''अर्थ कोई राय न होना नहीं है'', इसलिए चुप रहना ग़लत है; वह कहता है कि कुछ आदेश ठुकराने होंगे, इसलिए ''हर आदेश'' ग़लत है; और वह मंत्रियों द्वारा अधिकारियों की सलाह पर प्रश्न उठाने के बारे में कुछ नहीं कहता।','csat-l2-t03-rc-p05-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Author''s Tone','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
A civil servant in a democracy serves governments of every party in turn, and the system depends on her serving each of them with the same care. Neutrality does not mean having no views; it means giving honest advice in private and carrying out lawful decisions in public, even those she argued against. It also means knowing where the line lies. An order to bend a rule for a favoured contractor is not a decision to be loyally carried out but one to be refused, and the refusal recorded. Officials who confuse loyalty to the government of the day with loyalty to a minister''s wishes serve neither the public nor the minister: a policy that no one dared to question is a policy that no one has tested.

The author''s attitude towards officials who never question a minister''s wishes is best described as:','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
लोकतंत्र में एक सिविल सेवक बारी-बारी से हर दल की सरकारों की सेवा करती है, और व्यवस्था इस पर टिकी है कि वह हर एक की सेवा समान निष्ठा से करे। तटस्थता का अर्थ कोई राय न होना नहीं है; इसका अर्थ है निजी रूप से ईमानदार सलाह देना और सार्वजनिक रूप से वैध निर्णयों को लागू करना, उन निर्णयों को भी जिनके विरुद्ध उसने तर्क दिया था। इसका अर्थ यह जानना भी है कि रेखा कहाँ है। किसी चहेते ठेकेदार के लिए नियम मोड़ने का आदेश निष्ठा से लागू करने वाला निर्णय नहीं, बल्कि ठुकराने वाला आदेश है, और ठुकराने को लिखित में दर्ज किया जाना चाहिए। जो अधिकारी तत्कालीन सरकार के प्रति निष्ठा को किसी मंत्री की इच्छाओं के प्रति निष्ठा समझ बैठते हैं, वे न जनता का भला करते हैं न मंत्री का: जिस नीति पर किसी ने प्रश्न उठाने का साहस नहीं किया, उसे किसी ने परखा ही नहीं।

मंत्री की इच्छाओं पर कभी प्रश्न न उठाने वाले अधिकारियों के प्रति लेखक का दृष्टिकोण सबसे अच्छी तरह कैसा बताया जा सकता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p05", "csat_order": 33}'::jsonb,'[{"id": "a", "body": "admiring of their loyalty to the government of the day", "body_hi": "तत्कालीन सरकार के प्रति उनकी निष्ठा का प्रशंसक", "isCorrect": false}, {"id": "b", "body": "indifferent to the way they choose to behave", "body_hi": "उनके व्यवहार के ढंग के प्रति उदासीन", "isCorrect": false}, {"id": "c", "body": "critical of them for leaving policies untested", "body_hi": "नीतियों को बिना परखे छोड़ने के लिए उनका आलोचक", "isCorrect": true}, {"id": "d", "body": "sympathetic to the pressure under which they work", "body_hi": "जिस दबाव में वे काम करते हैं उसके प्रति सहानुभूतिपूर्ण", "isCorrect": false}]'::jsonb,2.5,0.83,'The author says such officials serve ''neither the public nor the minister'', because a policy no one dared to question has never been tested -- a critical view. Nothing in the passage admires their deference, the author is plainly not indifferent, and the passage does not dwell on the pressure officials work under.','लेखक कहता है कि ऐसे अधिकारी ''न जनता का भला करते हैं न मंत्री का'', क्योंकि जिस नीति पर किसी ने प्रश्न उठाने का साहस नहीं किया, उसे परखा ही नहीं गया -- यह आलोचनात्मक दृष्टि है। परिच्छेद में उनकी आज्ञाकारिता की कोई प्रशंसा नहीं, लेखक स्पष्ट रूप से उदासीन नहीं है, और परिच्छेद अधिकारियों पर पड़ने वाले दबाव की चर्चा नहीं करता।','csat-l2-t03-rc-p05-tone','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
A civil servant in a democracy serves governments of every party in turn, and the system depends on her serving each of them with the same care. Neutrality does not mean having no views; it means giving honest advice in private and carrying out lawful decisions in public, even those she argued against. It also means knowing where the line lies. An order to bend a rule for a favoured contractor is not a decision to be loyally carried out but one to be refused, and the refusal recorded. Officials who confuse loyalty to the government of the day with loyalty to a minister''s wishes serve neither the public nor the minister: a policy that no one dared to question is a policy that no one has tested.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
लोकतंत्र में एक सिविल सेवक बारी-बारी से हर दल की सरकारों की सेवा करती है, और व्यवस्था इस पर टिकी है कि वह हर एक की सेवा समान निष्ठा से करे। तटस्थता का अर्थ कोई राय न होना नहीं है; इसका अर्थ है निजी रूप से ईमानदार सलाह देना और सार्वजनिक रूप से वैध निर्णयों को लागू करना, उन निर्णयों को भी जिनके विरुद्ध उसने तर्क दिया था। इसका अर्थ यह जानना भी है कि रेखा कहाँ है। किसी चहेते ठेकेदार के लिए नियम मोड़ने का आदेश निष्ठा से लागू करने वाला निर्णय नहीं, बल्कि ठुकराने वाला आदेश है, और ठुकराने को लिखित में दर्ज किया जाना चाहिए। जो अधिकारी तत्कालीन सरकार के प्रति निष्ठा को किसी मंत्री की इच्छाओं के प्रति निष्ठा समझ बैठते हैं, वे न जनता का भला करते हैं न मंत्री का: जिस नीति पर किसी ने प्रश्न उठाने का साहस नहीं किया, उसे किसी ने परखा ही नहीं।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["Frank advice from officials can improve the quality of policy.", "An unlawful order does not become lawful because a minister gives it.", "Civil servants have no political views of their own."], "statements_hi": ["अधिकारियों की खरी सलाह नीति की गुणवत्ता सुधार सकती है।", "कोई अवैध आदेश केवल इसलिए वैध नहीं हो जाता कि उसे मंत्री ने दिया है।", "सिविल सेवकों के अपने कोई राजनीतिक विचार नहीं होते।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p05", "csat_order": 34}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "1 and 3 only", "body_hi": "केवल 1 और 3", "isCorrect": false}, {"id": "c", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}, {"id": "d", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": true}]'::jsonb,2.5,0.83,'1 and 2 are assumed. The closing line -- an unquestioned policy is an untested one -- takes for granted that frank advice can improve policy (1). The duty to refuse an order to bend a rule assumes that an unlawful order stays unlawful even when a minister gives it (2). 3 contradicts the passage: neutrality ''does not mean having no views''.','1 और 2 पूर्वधारणाएँ हैं। अंतिम पंक्ति -- जिस नीति पर प्रश्न नहीं उठा, वह परखी नहीं गई -- मानकर चलती है कि खरी सलाह नीति को बेहतर बना सकती है (1)। नियम मोड़ने के आदेश को ठुकराने का कर्तव्य मानता है कि अवैध आदेश मंत्री के देने पर भी अवैध ही रहता है (2)। 3 परिच्छेद का खंडन करता है: तटस्थता का ''अर्थ कोई राय न होना नहीं है''।','csat-l2-t03-rc-p05-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','statement_based','medium','Consider the integers from 1 to 500, both included. Which of the following statements is/are correct?','1 से 500 तक के पूर्णांकों पर विचार कीजिए, दोनों सम्मिलित। निम्नलिखित में से कौन-सा/से कथन सही है/हैं?','{"statements": ["Exactly 22 of them have an odd number of positive divisors.", "Every one of them that has an odd number of positive divisors is itself an odd number."], "statements_hi": ["उनमें से ठीक 22 के धनात्मक भाजकों की संख्या विषम है।", "उनमें से जिस भी संख्या के धनात्मक भाजकों की संख्या विषम है, वह स्वयं एक विषम संख्या है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l2-t03", "csat_order": 35}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": true}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only I is correct. Divisors come in pairs d and n/d, and one is left unpaired only when d = n/d, that is when n is a perfect square. So the numbers with an odd count of divisors are the squares 1², 2², ..., 22² = 484 (23² = 529 is too big): exactly 22. II confuses an odd number of divisors with an odd number: 4, a square, has the three divisors 1, 2 and 4 but is even.','केवल I सही है। भाजक जोड़ियों d और n/d में आते हैं, और कोई भाजक तभी अकेला बचता है जब d = n/d, यानी जब n पूर्ण वर्ग हो। अतः विषम संख्या में भाजकों वाली संख्याएँ वर्ग 1², 2², ..., 22² = 484 हैं (23² = 529 बहुत बड़ा है): ठीक 22। II भाजकों की विषम संख्या को विषम संख्या से भ्रमित करता है: 4 एक वर्ग है, उसके तीन भाजक 1, 2 और 4 हैं, पर वह सम है।','csat-l2-t03-qa-nt-odd-number-of-divisors','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','medium','Five lectures -- on History, Geography, Polity, Economy and Ethics -- are held on the five working days from Monday to Friday, one lecture a day. Polity is held on Wednesday. History is held on the day just before Economy. Ethics is held neither on Monday nor on Friday. Geography is held on a later day than Economy. On which day is the Geography lecture held?','पाँच व्याख्यान -- इतिहास, भूगोल, राजव्यवस्था, अर्थव्यवस्था और नीतिशास्त्र पर -- सोमवार से शुक्रवार तक के पाँच कार्यदिवसों पर, एक दिन में एक, होते हैं। राजव्यवस्था बुधवार को है। इतिहास, अर्थव्यवस्था से ठीक पहले वाले दिन है। नीतिशास्त्र न सोमवार को है, न शुक्रवार को। भूगोल, अर्थव्यवस्था के बाद के किसी दिन है। भूगोल का व्याख्यान किस दिन है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 36}'::jsonb,'[{"id": "a", "body": "Monday", "body_hi": "सोमवार", "isCorrect": false}, {"id": "b", "body": "Tuesday", "body_hi": "मंगलवार", "isCorrect": false}, {"id": "c", "body": "Thursday", "body_hi": "गुरुवार", "isCorrect": false}, {"id": "d", "body": "Friday", "body_hi": "शुक्रवार", "isCorrect": true}]'::jsonb,2.5,0.83,'With Wednesday taken by Polity, History and Economy, on consecutive days, are either Monday and Tuesday or Thursday and Friday. If Economy were on Friday, Geography could not come later, so History is on Monday and Economy on Tuesday. Ethics, kept off Monday and Friday, must be on Thursday, which leaves Friday for Geography. Monday is History''s day, Tuesday Economy''s and Thursday Ethics''s.','बुधवार राजव्यवस्था का होने से, लगातार दिनों वाले इतिहास और अर्थव्यवस्था या तो सोमवार-मंगलवार को हैं या गुरुवार-शुक्रवार को। यदि अर्थव्यवस्था शुक्रवार को होती, तो भूगोल उसके बाद नहीं आ सकता, इसलिए इतिहास सोमवार और अर्थव्यवस्था मंगलवार को है। सोमवार और शुक्रवार से बाहर रखा गया नीतिशास्त्र गुरुवार को ही होगा, जिससे शुक्रवार भूगोल के लिए बचता है। सोमवार इतिहास का, मंगलवार अर्थव्यवस्था का और गुरुवार नीतिशास्त्र का दिन है।','csat-l2-t03-lr-sa-week-of-lectures','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','₹1,560 is divided among A, B and C so that twice A''s share, three times B''s share and four times C''s share are all equal. What is A''s share?','₹1,560 को A, B और C में इस प्रकार बाँटा जाता है कि A के हिस्से का दोगुना, B के हिस्से का तीन गुना और C के हिस्से का चार गुना, तीनों बराबर हों। A का हिस्सा क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 37}'::jsonb,'[{"id": "a", "body": "₹360", "body_hi": "₹360", "isCorrect": false}, {"id": "b", "body": "₹480", "body_hi": "₹480", "isCorrect": false}, {"id": "c", "body": "₹520", "body_hi": "₹520", "isCorrect": false}, {"id": "d", "body": "₹720", "body_hi": "₹720", "isCorrect": true}]'::jsonb,2.5,0.83,'If 2A = 3B = 4C = k, then A = k/2, B = k/3 and C = k/4, so A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3. The 13 parts make ₹1,560, so one part is ₹120 and A gets 6 × 120 = ₹720. ₹480 and ₹360 are B''s and C''s shares; ₹520 splits the money equally.','यदि 2A = 3B = 4C = k, तो A = k/2, B = k/3 और C = k/4, अतः A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3। 13 भाग ₹1,560 हैं, इसलिए एक भाग ₹120 है और A को 6 × 120 = ₹720 मिलते हैं। ₹480 और ₹360, B और C के हिस्से हैं; ₹520 धन को बराबर बाँट देता है।','csat-l2-t03-qa-rm-twice-thrice-four-times','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','A sells a bicycle to B at a profit of 20%, and B sells it to C at a loss of 10%. If C pays ₹4,860 for it, how much did A pay for the bicycle?','A एक साइकिल B को 20% लाभ पर बेचता है, और B उसे C को 10% हानि पर बेचता है। यदि C उसके लिए ₹4,860 देता है, तो A ने साइकिल के लिए कितना दिया था?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 38}'::jsonb,'[{"id": "a", "body": "₹4,500", "body_hi": "₹4,500", "isCorrect": true}, {"id": "b", "body": "₹4,860", "body_hi": "₹4,860", "isCorrect": false}, {"id": "c", "body": "₹5,400", "body_hi": "₹5,400", "isCorrect": false}, {"id": "d", "body": "₹5,832", "body_hi": "₹5,832", "isCorrect": false}]'::jsonb,2.5,0.83,'If A paid P, B paid 1.2P, and C paid 0.9 × 1.2P = 1.08P = ₹4,860, so P = 4,860/1.08 = ₹4,500. ₹5,400 is what B paid (4,860/0.9); ₹4,860 is C''s price; ₹5,832 multiplies C''s price by 1.2 instead of working back.','यदि A ने P दिया, तो B ने 1.2P दिया, और C ने 0.9 × 1.2P = 1.08P = ₹4,860 दिया, अतः P = 4,860/1.08 = ₹4,500। ₹5,400 वह है जो B ने दिया (4,860/0.9); ₹4,860, C का मूल्य है; ₹5,832, पीछे की ओर गणना करने के बजाय C के मूल्य को 1.2 से गुणा कर देता है।','csat-l2-t03-qa-pp-chain-of-two-sales','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
India grows more fruit and vegetables than almost any other country, yet a sizeable share spoils between the farm and the plate. Much of the loss happens before the food reaches a shop: produce picked in the heat waits for a truck, travels without cooling, and is sold at whatever price the market will bear before it rots. Cold storage exists, but much of it is built for potatoes, lies far from the farms and is of little use for a tomato that must be cooled within hours of picking. What would make the most difference is less glamorous than large warehouses: small cooling units near the farms, run on solar power where the grid is weak, and trucks that keep the cold chain unbroken.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत लगभग किसी भी अन्य देश से अधिक फल और सब्ज़ियाँ उगाता है, फिर भी उनका एक बड़ा भाग खेत और थाली के बीच ख़राब हो जाता है। अधिकांश हानि भोजन के दुकान तक पहुँचने से पहले होती है: गर्मी में तोड़ी गई उपज ट्रक की प्रतीक्षा करती है, बिना ठंडक के यात्रा करती है, और सड़ने से पहले बाज़ार जो भी दाम दे, उस पर बिक जाती है। शीत भंडार मौजूद हैं, पर उनका बड़ा भाग आलू के लिए बना है, खेतों से दूर है, और ऐसे टमाटर के लिए किसी काम का नहीं जिसे तोड़ने के कुछ ही घंटों के भीतर ठंडा करना ज़रूरी है। सबसे बड़ा अंतर बड़े गोदामों से कम आकर्षक चीज़ों से आएगा: खेतों के पास छोटी शीतलन इकाइयाँ, जो बिजली ग्रिड कमज़ोर होने पर सौर ऊर्जा से चलें, और ऐसे ट्रक जो शीत शृंखला को टूटने न दें।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p06", "csat_order": 39}'::jsonb,'[{"id": "a", "body": "India grows far more fruit and vegetables than its people are able to eat.", "body_hi": "भारत अपने लोगों के खा सकने से कहीं अधिक फल और सब्ज़ियाँ उगाता है।", "isCorrect": false}, {"id": "b", "body": "Most of India''s food is wasted in homes and shops rather than on the way to them.", "body_hi": "भारत का अधिकांश भोजन वहाँ तक पहुँचने के रास्ते में नहीं, घरों और दुकानों में बर्बाद होता है।", "isCorrect": false}, {"id": "c", "body": "The cold stores that are now used for potatoes should be closed down.", "body_hi": "जो शीत भंडार अभी आलू के लिए उपयोग होते हैं, उन्हें बंद कर देना चाहिए।", "isCorrect": false}, {"id": "d", "body": "Cutting food loss needs cooling close to the farms more than distant cold stores.", "body_hi": "भोजन की हानि घटाने के लिए दूर के शीत भंडारों से अधिक खेतों के पास ठंडक चाहिए।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage places most of the loss between picking and the shop, finds the existing stores built for potatoes and far away, and ends by calling for small cooling units near farms and an unbroken cold chain. It says nothing of India growing too much; it places the loss before food reaches a shop, not in homes and shops; and it does not ask for the potato stores to be closed.','परिच्छेद अधिकांश हानि तोड़ने और दुकान के बीच बताता है, पाता है कि मौजूदा भंडार आलू के लिए बने और दूर हैं, और अंत में खेतों के पास छोटी शीतलन इकाइयों और न टूटने वाली शीत शृंखला की माँग करता है। वह भारत के बहुत अधिक उगाने की कोई बात नहीं करता; वह हानि को भोजन के दुकान पहुँचने से पहले रखता है, घरों और दुकानों में नहीं; और वह आलू के भंडार बंद करने को नहीं कहता।','csat-l2-t03-rc-p06-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
India grows more fruit and vegetables than almost any other country, yet a sizeable share spoils between the farm and the plate. Much of the loss happens before the food reaches a shop: produce picked in the heat waits for a truck, travels without cooling, and is sold at whatever price the market will bear before it rots. Cold storage exists, but much of it is built for potatoes, lies far from the farms and is of little use for a tomato that must be cooled within hours of picking. What would make the most difference is less glamorous than large warehouses: small cooling units near the farms, run on solar power where the grid is weak, and trucks that keep the cold chain unbroken.

According to the passage, why is much of the existing cold storage of little use for tomatoes?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत लगभग किसी भी अन्य देश से अधिक फल और सब्ज़ियाँ उगाता है, फिर भी उनका एक बड़ा भाग खेत और थाली के बीच ख़राब हो जाता है। अधिकांश हानि भोजन के दुकान तक पहुँचने से पहले होती है: गर्मी में तोड़ी गई उपज ट्रक की प्रतीक्षा करती है, बिना ठंडक के यात्रा करती है, और सड़ने से पहले बाज़ार जो भी दाम दे, उस पर बिक जाती है। शीत भंडार मौजूद हैं, पर उनका बड़ा भाग आलू के लिए बना है, खेतों से दूर है, और ऐसे टमाटर के लिए किसी काम का नहीं जिसे तोड़ने के कुछ ही घंटों के भीतर ठंडा करना ज़रूरी है। सबसे बड़ा अंतर बड़े गोदामों से कम आकर्षक चीज़ों से आएगा: खेतों के पास छोटी शीतलन इकाइयाँ, जो बिजली ग्रिड कमज़ोर होने पर सौर ऊर्जा से चलें, और ऐसे ट्रक जो शीत शृंखला को टूटने न दें।

परिच्छेद के अनुसार, मौजूदा शीत भंडारों का बड़ा भाग टमाटरों के लिए किसी काम का क्यों नहीं है?','{"craft": "precision", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p06", "csat_order": 40}'::jsonb,'[{"id": "a", "body": "It runs on solar power, which fails when the weather is cloudy.", "body_hi": "वे सौर ऊर्जा से चलते हैं, जो बादल होने पर काम नहीं करती।", "isCorrect": false}, {"id": "b", "body": "It is built for potatoes and lies far from the farms.", "body_hi": "उनका बड़ा भाग आलू के लिए बना है और खेतों से दूर है।", "isCorrect": true}, {"id": "c", "body": "Tomatoes spoil just as quickly whether they are cooled or not.", "body_hi": "टमाटर ठंडे किए जाएँ या नहीं, उतनी ही जल्दी ख़राब होते हैं।", "isCorrect": false}, {"id": "d", "body": "Traders find the charges for storing tomatoes there too high.", "body_hi": "व्यापारियों को वहाँ टमाटर रखने का शुल्क बहुत अधिक लगता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says that much of the cold storage ''is built for potatoes, lies far from the farms'' and so is of little use for a tomato that must be cooled within hours. Solar power appears only in the new units the passage proposes; the passage implies that tomatoes do gain from quick cooling; and storage charges are not mentioned.','परिच्छेद कहता है कि शीत भंडारों का बड़ा भाग ''आलू के लिए बना है, खेतों से दूर है'' और इसलिए ऐसे टमाटर के किसी काम का नहीं जिसे कुछ ही घंटों में ठंडा करना ज़रूरी है। सौर ऊर्जा केवल उन नई इकाइयों में आती है जिनका परिच्छेद प्रस्ताव करता है; परिच्छेद से स्पष्ट है कि टमाटरों को जल्दी ठंडा करने से लाभ होता है; और भंडारण शुल्क का कोई उल्लेख नहीं।','csat-l2-t03-rc-p06-detail','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
India grows more fruit and vegetables than almost any other country, yet a sizeable share spoils between the farm and the plate. Much of the loss happens before the food reaches a shop: produce picked in the heat waits for a truck, travels without cooling, and is sold at whatever price the market will bear before it rots. Cold storage exists, but much of it is built for potatoes, lies far from the farms and is of little use for a tomato that must be cooled within hours of picking. What would make the most difference is less glamorous than large warehouses: small cooling units near the farms, run on solar power where the grid is weak, and trucks that keep the cold chain unbroken.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत लगभग किसी भी अन्य देश से अधिक फल और सब्ज़ियाँ उगाता है, फिर भी उनका एक बड़ा भाग खेत और थाली के बीच ख़राब हो जाता है। अधिकांश हानि भोजन के दुकान तक पहुँचने से पहले होती है: गर्मी में तोड़ी गई उपज ट्रक की प्रतीक्षा करती है, बिना ठंडक के यात्रा करती है, और सड़ने से पहले बाज़ार जो भी दाम दे, उस पर बिक जाती है। शीत भंडार मौजूद हैं, पर उनका बड़ा भाग आलू के लिए बना है, खेतों से दूर है, और ऐसे टमाटर के लिए किसी काम का नहीं जिसे तोड़ने के कुछ ही घंटों के भीतर ठंडा करना ज़रूरी है। सबसे बड़ा अंतर बड़े गोदामों से कम आकर्षक चीज़ों से आएगा: खेतों के पास छोटी शीतलन इकाइयाँ, जो बिजली ग्रिड कमज़ोर होने पर सौर ऊर्जा से चलें, और ऐसे ट्रक जो शीत शृंखला को टूटने न दें।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Produce that is cooled soon after it is picked is likely to keep longer.", "Where the electricity grid is weak, solar power can help keep produce cool near the farms."], "statements_hi": ["तोड़ने के तुरंत बाद ठंडी की गई उपज के अधिक समय तक टिकने की संभावना है।", "जहाँ बिजली ग्रिड कमज़ोर है, वहाँ सौर ऊर्जा खेतों के पास उपज को ठंडा रखने में मदद कर सकती है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p06", "csat_order": 41}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. A tomato ''must be cooled within hours of picking'', and produce that travels without cooling rots, so cooling soon after picking helps produce keep (1). The passage proposes cooling units near the farms ''run on solar power where the grid is weak'' (2).','दोनों वैध हैं। टमाटर को ''तोड़ने के कुछ ही घंटों के भीतर ठंडा करना ज़रूरी है'', और बिना ठंडक के यात्रा करने वाली उपज सड़ जाती है, इसलिए तोड़ने के तुरंत बाद ठंडा करने से उपज टिकती है (1)। परिच्छेद खेतों के पास ऐसी शीतलन इकाइयों का प्रस्ताव करता है ''जो बिजली ग्रिड कमज़ोर होने पर सौर ऊर्जा से चलें'' (2)।','csat-l2-t03-rc-p06-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Cube Painting','mcq','hard','A wooden block 4 cm long, 3 cm wide and 2 cm high is painted on all its faces and then cut into 1 cm cubes. How many of the small cubes have exactly one painted face?','4 सेमी लंबे, 3 सेमी चौड़े और 2 सेमी ऊँचे लकड़ी के एक गुटके को सभी फलकों पर रँगकर 1 सेमी के घनों में काटा जाता है। कितने छोटे घनों का ठीक एक फलक रँगा है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 42}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "b", "body": "4", "body_hi": "4", "isCorrect": true}, {"id": "c", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "d", "body": "12", "body_hi": "12", "isCorrect": false}]'::jsonb,2.5,0.83,'The block gives 4 × 3 × 2 = 24 cubes. A cube has exactly one painted face only if it lies inside a face, away from all its edges. On each of the two 4 × 3 faces that leaves (4 - 2)(3 - 2) = 2 cubes; the 4 × 2 and 3 × 2 faces leave none, because a face only 2 cm across is all edge. So 2 + 2 = 4. 12 is the number with exactly two painted faces and 8 the corners, with three; 0 is the number with no painted face, since a block only 2 cm high has no hidden inside.','गुटके से 4 × 3 × 2 = 24 घन बनते हैं। किसी घन का ठीक एक फलक तभी रँगा होता है जब वह किसी फलक के भीतर, उसके सभी किनारों से दूर, हो। दोनों 4 × 3 फलकों में से हर एक पर ऐसे (4 - 2)(3 - 2) = 2 घन बचते हैं; 4 × 2 और 3 × 2 फलकों पर कोई नहीं, क्योंकि केवल 2 सेमी चौड़ा फलक पूरा किनारा ही है। अतः 2 + 2 = 4। 12 ठीक दो रँगे फलकों वाले घनों की संख्या है और 8 कोनों की, जिनके तीन फलक रँगे हैं; 0 बिना रँगे घनों की संख्या है, क्योंकि केवल 2 सेमी ऊँचे गुटके का कोई छिपा भीतरी भाग नहीं होता।','csat-l2-t03-lr-cp-block-4-by-3-by-2','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the sum of all the odd divisors of 360?','360 के सभी विषम भाजकों का योग क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 43}'::jsonb,'[{"id": "a", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "b", "body": "45", "body_hi": "45", "isCorrect": false}, {"id": "c", "body": "78", "body_hi": "78", "isCorrect": true}, {"id": "d", "body": "1170", "body_hi": "1170", "isCorrect": false}]'::jsonb,2.5,0.83,'360 = 2³ × 3² × 5. An odd divisor can take no factor of 2, so the odd divisors are the divisors of 3² × 5 = 45: 1, 3, 5, 9, 15 and 45. Their sum is (1 + 3 + 9)(1 + 5) = 13 × 6 = 78. 6 is how many odd divisors there are; 45 is the largest of them; 1170 is the sum of all the divisors of 360, odd and even.','360 = 2³ × 3² × 5। विषम भाजक में 2 का कोई गुणनखंड नहीं हो सकता, इसलिए विषम भाजक 3² × 5 = 45 के भाजक हैं: 1, 3, 5, 9, 15 और 45। इनका योग (1 + 3 + 9)(1 + 5) = 13 × 6 = 78 है। 6 विषम भाजकों की संख्या है; 45 उनमें सबसे बड़ा है; 1170, 360 के सभी भाजकों, सम और विषम, का योग है।','csat-l2-t03-qa-nt-sum-of-odd-divisors-360','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','hard','A boy walks up an escalator that is moving upwards. Taking one step a second, he reaches the top in 20 seconds; taking two steps a second, he reaches the top in 15 seconds. How many steps of the escalator are visible from the bottom to the top?','एक लड़का ऊपर की ओर चलती एस्केलेटर पर चढ़ता है। एक सेकंड में एक सीढ़ी चढ़ते हुए वह 20 सेकंड में ऊपर पहुँचता है; एक सेकंड में दो सीढ़ियाँ चढ़ते हुए 15 सेकंड में। नीचे से ऊपर तक एस्केलेटर की कितनी सीढ़ियाँ दिखाई देती हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 44}'::jsonb,'[{"id": "a", "body": "30", "body_hi": "30", "isCorrect": false}, {"id": "b", "body": "40", "body_hi": "40", "isCorrect": false}, {"id": "c", "body": "60", "body_hi": "60", "isCorrect": true}, {"id": "d", "body": "120", "body_hi": "120", "isCorrect": false}]'::jsonb,2.5,0.83,'Let the escalator carry e steps a second. The visible steps are covered by the boy''s own steps plus the escalator''s: 20 × 1 + 20e on the slow climb and 15 × 2 + 15e on the fast one. So 20 + 20e = 30 + 15e, giving e = 2 and 20 + 40 = 60 steps. 30 counts only the boy''s steps on the fast climb and 40 only the escalator''s on the slow one; 120 adds the two climbs together.','मान लीजिए एस्केलेटर एक सेकंड में e सीढ़ियाँ ले जाती है। दिखाई देने वाली सीढ़ियाँ लड़के की अपनी सीढ़ियों और एस्केलेटर की सीढ़ियों से मिलकर तय होती हैं: धीमी चढ़ाई में 20 × 1 + 20e और तेज़ चढ़ाई में 15 × 2 + 15e। अतः 20 + 20e = 30 + 15e, जिससे e = 2 और 20 + 40 = 60 सीढ़ियाँ। 30 तेज़ चढ़ाई में केवल लड़के की सीढ़ियाँ गिनता है और 40 धीमी चढ़ाई में केवल एस्केलेटर की; 120 दोनों चढ़ाइयों को जोड़ देता है।','csat-l2-t03-qa-sdt-escalator-steps','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Syllogism','statement_based','medium','Statements: All roses are flowers. No flower is a stone. Some stones are red.

Which of the following conclusions follow(s) from the statements?','कथन: सभी गुलाब फूल हैं। कोई भी फूल पत्थर नहीं है। कुछ पत्थर लाल हैं।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथनों से निकलता/निकलते है/हैं?','{"statements": ["Some red things are roses.", "No stone is a rose."], "statements_hi": ["कुछ लाल वस्तुएँ गुलाब हैं।", "कोई भी पत्थर गुलाब नहीं है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l2-t03", "csat_order": 45}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": false}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": true}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only II follows: every rose is a flower and no flower is a stone, so no rose can be a stone. I does not follow: the only red things the statements mention are stones, and no stone is a rose; roses may or may not be red, so ''some red things are roses'' is possible but not certain. The red stones are a red herring for I.','केवल II निकलता है: हर गुलाब फूल है और कोई फूल पत्थर नहीं है, इसलिए कोई गुलाब पत्थर नहीं हो सकता। I नहीं निकलता: कथनों में जिन लाल वस्तुओं का उल्लेख है वे केवल पत्थर हैं, और कोई पत्थर गुलाब नहीं है; गुलाब लाल हो भी सकते हैं और नहीं भी, इसलिए ''कुछ लाल वस्तुएँ गुलाब हैं'' संभव है पर निश्चित नहीं। लाल पत्थर I के लिए केवल भटकाने वाली बात हैं।','csat-l2-t03-lr-sy-roses-flowers-stones','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','3 pens and 4 pencils cost ₹46, and 5 pens and 2 pencils cost ₹58. What do one pen and one pencil cost together?','3 पेन और 4 पेंसिल का मूल्य ₹46 है, और 5 पेन और 2 पेंसिल का ₹58। एक पेन और एक पेंसिल का कुल मूल्य क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 46}'::jsonb,'[{"id": "a", "body": "₹6", "body_hi": "₹6", "isCorrect": false}, {"id": "b", "body": "₹10", "body_hi": "₹10", "isCorrect": false}, {"id": "c", "body": "₹13", "body_hi": "₹13", "isCorrect": false}, {"id": "d", "body": "₹14", "body_hi": "₹14", "isCorrect": true}]'::jsonb,2.5,0.83,'Doubling the second purchase gives 10 pens + 4 pencils = ₹116; taking away the first leaves 7 pens = ₹70, so a pen costs ₹10, and then 4 pencils cost 46 - 30 = ₹16, so a pencil costs ₹4. Together, ₹14. ₹10 is the pen alone; ₹6 is the difference between a pen and a pencil; ₹13 divides the sum of the two purchases, 8 pens + 6 pencils = ₹104, by 8 as if both counts were 8.','दूसरी ख़रीद को दोगुना करने पर 10 पेन + 4 पेंसिल = ₹116; इसमें से पहली घटाने पर 7 पेन = ₹70, अतः एक पेन ₹10 का है, और फिर 4 पेंसिल 46 - 30 = ₹16 की, यानी एक पेंसिल ₹4 की। दोनों मिलकर ₹14। ₹10 केवल पेन है; ₹6 पेन और पेंसिल का अंतर है; ₹13 दोनों ख़रीदों के योग, 8 पेन + 6 पेंसिल = ₹104, को 8 से भाग देता है, मानो दोनों गिनतियाँ 8 हों।','csat-l2-t03-qa-ph-pens-and-pencils','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Best Summary','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Hill towns in the Himalaya were built for a few thousand residents and now receive that many visitors in a single day in the season. Roads are widened to bring them in, hotels rise on slopes that were never surveyed for such loads, and the streams that once carried away a town''s waste now carry far more. Each new road brings more cars, and each wider road invites more hotels; the town''s appeal, its quiet and its views, is the first thing to go. Some places have begun to limit the number of vehicles or visitors on a given day. Such limits are unpopular with those who earn from tourism, but they may be what keeps the trade alive.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हिमालय के पहाड़ी कस्बे कुछ हज़ार निवासियों के लिए बसे थे और अब मौसम में एक ही दिन में उतने पर्यटक आ जाते हैं। उन्हें लाने के लिए सड़कें चौड़ी की जाती हैं, ऐसी ढलानों पर होटल उठते हैं जिनका इतने भार के लिए कभी सर्वेक्षण नहीं हुआ, और जो नाले कभी कस्बे का कचरा बहा ले जाते थे, वे अब कहीं अधिक ढोते हैं। हर नई सड़क अधिक गाड़ियाँ लाती है, और हर चौड़ी सड़क अधिक होटलों को न्योता देती है; कस्बे का आकर्षण, उसकी शांति और उसके दृश्य, सबसे पहले जाते हैं। कुछ स्थानों ने किसी एक दिन में गाड़ियों या पर्यटकों की संख्या सीमित करना शुरू किया है। ऐसी सीमाएँ पर्यटन से कमाने वालों में अलोकप्रिय हैं, पर हो सकता है कि यही उस व्यापार को जीवित रखें।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p07", "csat_order": 47}'::jsonb,'[{"id": "a", "body": "Unchecked tourism wears away what draws visitors, so limits may save the trade.", "body_hi": "बेरोक पर्यटन वही घिसता है जो पर्यटकों को खींचता है; सीमाएँ व्यापार बचा सकती हैं।", "isCorrect": true}, {"id": "b", "body": "Tourism should be banned in Himalayan towns to protect their streams and slopes.", "body_hi": "हिमालयी कस्बों के नालों और ढलानों की रक्षा के लिए वहाँ पर्यटन पर प्रतिबंध लगना चाहिए।", "isCorrect": false}, {"id": "c", "body": "Wider roads are the best way for hill towns to cope with the crowds of tourists.", "body_hi": "पहाड़ी कस्बों के लिए पर्यटकों की भीड़ से निपटने का सबसे अच्छा तरीका चौड़ी सड़कें हैं।", "isCorrect": false}, {"id": "d", "body": "People who earn their living from tourism have welcomed the limits on visitors.", "body_hi": "पर्यटन से जीविका कमाने वालों ने पर्यटकों पर लगी सीमाओं का स्वागत किया है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage traces how the roads and hotels built for visitors destroy the quiet and views that draw them, and suggests that daily limits, though unpopular, may keep tourism alive. It proposes limits, not a ban; it presents wider roads as part of the problem; and it says the limits are unpopular with those who earn from tourism.','परिच्छेद दिखाता है कि पर्यटकों के लिए बनी सड़कें और होटल उस शांति और उन दृश्यों को नष्ट करते हैं जो उन्हें खींचते हैं, और सुझाता है कि दैनिक सीमाएँ, अलोकप्रिय होने पर भी, पर्यटन को जीवित रख सकती हैं। वह सीमाओं का प्रस्ताव करता है, प्रतिबंध का नहीं; वह चौड़ी सड़कों को समस्या का भाग बताता है; और वह कहता है कि सीमाएँ पर्यटन से कमाने वालों में अलोकप्रिय हैं।','csat-l2-t03-rc-p07-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Hill towns in the Himalaya were built for a few thousand residents and now receive that many visitors in a single day in the season. Roads are widened to bring them in, hotels rise on slopes that were never surveyed for such loads, and the streams that once carried away a town''s waste now carry far more. Each new road brings more cars, and each wider road invites more hotels; the town''s appeal, its quiet and its views, is the first thing to go. Some places have begun to limit the number of vehicles or visitors on a given day. Such limits are unpopular with those who earn from tourism, but they may be what keeps the trade alive.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हिमालय के पहाड़ी कस्बे कुछ हज़ार निवासियों के लिए बसे थे और अब मौसम में एक ही दिन में उतने पर्यटक आ जाते हैं। उन्हें लाने के लिए सड़कें चौड़ी की जाती हैं, ऐसी ढलानों पर होटल उठते हैं जिनका इतने भार के लिए कभी सर्वेक्षण नहीं हुआ, और जो नाले कभी कस्बे का कचरा बहा ले जाते थे, वे अब कहीं अधिक ढोते हैं। हर नई सड़क अधिक गाड़ियाँ लाती है, और हर चौड़ी सड़क अधिक होटलों को न्योता देती है; कस्बे का आकर्षण, उसकी शांति और उसके दृश्य, सबसे पहले जाते हैं। कुछ स्थानों ने किसी एक दिन में गाड़ियों या पर्यटकों की संख्या सीमित करना शुरू किया है। ऐसी सीमाएँ पर्यटन से कमाने वालों में अलोकप्रिय हैं, पर हो सकता है कि यही उस व्यापार को जीवित रखें।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["All visitors to hill towns arrive by car.", "A town''s quiet and its views are part of what draws visitors to it."], "statements_hi": ["पहाड़ी कस्बों में सभी पर्यटक कार से आते हैं।", "किसी कस्बे की शांति और उसके दृश्य उन कारणों में हैं जो पर्यटकों को वहाँ खींचते हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p07", "csat_order": 48}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is assumed. The claim that limits ''may be what keeps the trade alive'' rests on the idea that a town''s quiet and views draw its visitors -- lose them and the visitors go. 1 is not needed: the passage speaks of limiting ''vehicles or visitors'', and nothing depends on every visitor coming by car.','केवल 2 पूर्वधारणा है। यह दावा कि सीमाएँ ''हो सकता है उस व्यापार को जीवित रखें'', इस विचार पर टिका है कि कस्बे की शांति और उसके दृश्य पर्यटकों को खींचते हैं -- वे गए तो पर्यटक भी जाएँगे। 1 की ज़रूरत नहीं: परिच्छेद ''गाड़ियों या पर्यटकों'' को सीमित करने की बात करता है, और कुछ भी इस पर निर्भर नहीं कि हर पर्यटक कार से आए।','csat-l2-t03-rc-p07-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Hill towns in the Himalaya were built for a few thousand residents and now receive that many visitors in a single day in the season. Roads are widened to bring them in, hotels rise on slopes that were never surveyed for such loads, and the streams that once carried away a town''s waste now carry far more. Each new road brings more cars, and each wider road invites more hotels; the town''s appeal, its quiet and its views, is the first thing to go. Some places have begun to limit the number of vehicles or visitors on a given day. Such limits are unpopular with those who earn from tourism, but they may be what keeps the trade alive.

Which of the following inferences can be drawn from the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हिमालय के पहाड़ी कस्बे कुछ हज़ार निवासियों के लिए बसे थे और अब मौसम में एक ही दिन में उतने पर्यटक आ जाते हैं। उन्हें लाने के लिए सड़कें चौड़ी की जाती हैं, ऐसी ढलानों पर होटल उठते हैं जिनका इतने भार के लिए कभी सर्वेक्षण नहीं हुआ, और जो नाले कभी कस्बे का कचरा बहा ले जाते थे, वे अब कहीं अधिक ढोते हैं। हर नई सड़क अधिक गाड़ियाँ लाती है, और हर चौड़ी सड़क अधिक होटलों को न्योता देती है; कस्बे का आकर्षण, उसकी शांति और उसके दृश्य, सबसे पहले जाते हैं। कुछ स्थानों ने किसी एक दिन में गाड़ियों या पर्यटकों की संख्या सीमित करना शुरू किया है। ऐसी सीमाएँ पर्यटन से कमाने वालों में अलोकप्रिय हैं, पर हो सकता है कि यही उस व्यापार को जीवित रखें।

परिच्छेद से निम्नलिखित में से कौन-से अनुमान निकाले जा सकते हैं?','{"statements": ["Widening the roads into a hill town can bring more traffic rather than less.", "Some hotels may stand on slopes that were never checked for the load they carry.", "Limits on visitors are welcomed by everyone who earns from tourism."], "statements_hi": ["पहाड़ी कस्बे की सड़कें चौड़ी करने से यातायात घटने के बजाय बढ़ सकता है।", "कुछ होटल ऐसी ढलानों पर हो सकते हैं जिनकी उस भार के लिए कभी जाँच नहीं हुई जो वे ढोती हैं।", "पर्यटन से कमाने वाले सभी लोग पर्यटकों पर सीमाओं का स्वागत करते हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p07", "csat_order": 49}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": true}, {"id": "c", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "body_hi": "1, 2 और 3", "isCorrect": false}]'::jsonb,2.5,0.83,'1 and 2 follow. ''Each new road brings more cars, and each wider road invites more hotels'', so widening the roads into a hill town can add to its traffic (1); the hotels rise ''on slopes that were never surveyed for such loads'' (2). 3 contradicts the passage, which says the limits are unpopular with those who earn from tourism.','1 और 2 निकलते हैं। ''हर नई सड़क अधिक गाड़ियाँ लाती है, और हर चौड़ी सड़क अधिक होटलों को न्योता देती है'', इसलिए पहाड़ी कस्बे की सड़कें चौड़ी करने से उसका यातायात बढ़ सकता है (1); होटल ''ऐसी ढलानों पर उठते हैं जिनका इतने भार के लिए कभी सर्वेक्षण नहीं हुआ'' (2)। 3 परिच्छेद का खंडन करता है, जो कहता है कि सीमाएँ पर्यटन से कमाने वालों में अलोकप्रिय हैं।','csat-l2-t03-rc-p07-inferences','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','A number leaves a remainder of 36 when divided by 136. What remainder will it leave when divided by 17?','कोई संख्या 136 से भाग देने पर 36 शेषफल छोड़ती है। 17 से भाग देने पर वह कितना शेषफल छोड़ेगी?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 50}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": true}, {"id": "b", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "c", "body": "19", "body_hi": "19", "isCorrect": false}, {"id": "d", "body": "36", "body_hi": "36", "isCorrect": false}]'::jsonb,2.5,0.83,'The number is 136k + 36 for some whole number k. Since 136 = 17 × 8, the part 136k is a multiple of 17, so the remainder comes from 36 alone: 36 = 17 × 2 + 2, remainder 2. 36 keeps the old remainder, which is larger than 17; 19 subtracts 17 only once; 8 is the quotient 136 ÷ 17, not a remainder.','संख्या किसी पूर्ण संख्या k के लिए 136k + 36 है। चूँकि 136 = 17 × 8, भाग 136k, 17 का गुणज है, इसलिए शेषफल केवल 36 से आता है: 36 = 17 × 2 + 2, शेषफल 2। 36 पुराना शेषफल ही रखता है, जो 17 से बड़ा है; 19 केवल एक बार 17 घटाता है; 8 भागफल 136 ÷ 17 है, शेषफल नहीं।','csat-l2-t03-qa-nt-remainder-136-then-17','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Truth-Liar','mcq','hard','Each of two people, A and B, is either a truth-teller, who always tells the truth, or a liar, who always lies. A says, ''At least one of us is a liar.'' Which of the following must be true?','दो व्यक्तियों, A और B, में से हर एक या तो सत्यवादी है, जो सदा सच बोलता है, या झूठा, जो सदा झूठ बोलता है। A कहता है, ''हम दोनों में से कम से कम एक झूठा है।'' निम्नलिखित में से क्या अवश्य सत्य है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 51}'::jsonb,'[{"id": "a", "body": "Both are truth-tellers", "body_hi": "दोनों सत्यवादी हैं", "isCorrect": false}, {"id": "b", "body": "A is a truth-teller and B is a liar", "body_hi": "A सत्यवादी है और B झूठा", "isCorrect": true}, {"id": "c", "body": "A is a liar and B is a truth-teller", "body_hi": "A झूठा है और B सत्यवादी", "isCorrect": false}, {"id": "d", "body": "Both are liars", "body_hi": "दोनों झूठे हैं", "isCorrect": false}]'::jsonb,2.5,0.83,'Suppose A is a liar. Then ''at least one of us is a liar'' is true, because A is one -- but a liar cannot say anything true. So A is a truth-teller, and the statement is true: one of the two is a liar, and it can only be B. ''Both are liars'' fails in the same way as A being a liar; ''both are truth-tellers'' would make A''s statement false.','मान लीजिए A झूठा है। तब ''हम दोनों में से कम से कम एक झूठा है'' सत्य है, क्योंकि A स्वयं झूठा है -- पर झूठा कोई सच्ची बात नहीं कह सकता। अतः A सत्यवादी है, और कथन सत्य है: दोनों में से एक झूठा है, और वह केवल B हो सकता है। ''दोनों झूठे हैं'' उसी तरह विफल होता है जैसे A का झूठा होना; ''दोनों सत्यवादी हैं'' A के कथन को असत्य बना देता।','csat-l2-t03-lr-tl-at-least-one-liar','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A 60-litre mixture contains milk and water in the ratio 2 : 1. How much water must be added to it to make the ratio of milk to water 1 : 2?','60 लीटर के एक मिश्रण में दूध और पानी 2 : 1 के अनुपात में हैं। दूध और पानी का अनुपात 1 : 2 करने के लिए उसमें कितना पानी मिलाना होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 52}'::jsonb,'[{"id": "a", "body": "40 litres", "body_hi": "40 लीटर", "isCorrect": false}, {"id": "b", "body": "60 litres", "body_hi": "60 लीटर", "isCorrect": true}, {"id": "c", "body": "80 litres", "body_hi": "80 लीटर", "isCorrect": false}, {"id": "d", "body": "120 litres", "body_hi": "120 लीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'The mixture holds 40 litres of milk and 20 of water. Adding water leaves the milk at 40 litres, so for a ratio of 1 : 2 the water must reach 80 litres: 60 litres must be added. 80 litres is the water needed in all, not the amount to add; 40 litres is the milk; 120 litres doubles the whole mixture.','मिश्रण में 40 लीटर दूध और 20 लीटर पानी है। पानी मिलाने से दूध 40 लीटर ही रहता है, इसलिए 1 : 2 के अनुपात के लिए पानी 80 लीटर होना चाहिए: 60 लीटर मिलाना होगा। 80 लीटर कुल आवश्यक पानी है, मिलाई जाने वाली मात्रा नहीं; 40 लीटर दूध है; 120 लीटर पूरे मिश्रण को दोगुना कर देता है।','csat-l2-t03-qa-rm-water-to-reverse-ratio','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','hard','One number in the series 4, 6, 12, 30, 96, 315, 1260 is wrong. Which one is it?','श्रेणी 4, 6, 12, 30, 96, 315, 1260 में एक संख्या ग़लत है। वह कौन-सी है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 53}'::jsonb,'[{"id": "a", "body": "30", "body_hi": "30", "isCorrect": false}, {"id": "b", "body": "96", "body_hi": "96", "isCorrect": true}, {"id": "c", "body": "315", "body_hi": "315", "isCorrect": false}, {"id": "d", "body": "1260", "body_hi": "1260", "isCorrect": false}]'::jsonb,2.5,0.83,'The multipliers rise by 0.5 at each step: 4 × 1.5 = 6, 6 × 2 = 12, 12 × 2.5 = 30, 30 × 3 = 90, 90 × 3.5 = 315 and 315 × 4 = 1260. The fifth term should be 90: with 96, both 30 → 96 and 96 → 315 break the pattern, while every other step fits. 315 looks out of place because 3.5 is not a whole number, but it is exactly 90 × 3.5; 30 and 1260 fit their neighbours on both sides.','गुणक हर चरण पर 0.5 बढ़ते हैं: 4 × 1.5 = 6, 6 × 2 = 12, 12 × 2.5 = 30, 30 × 3 = 90, 90 × 3.5 = 315 और 315 × 4 = 1260। पाँचवाँ पद 90 होना चाहिए: 96 के साथ 30 → 96 और 96 → 315 दोनों क्रम तोड़ते हैं, जबकि बाक़ी हर चरण ठीक बैठता है। 315 अटपटा लगता है क्योंकि 3.5 पूर्ण संख्या नहीं है, पर वह ठीक 90 × 3.5 है; 30 और 1260 अपने दोनों ओर के पदों से मेल खाते हैं।','csat-l2-t03-qa-ss-wrong-term-rising-multipliers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Governments have long changed behaviour with laws and taxes. A newer approach changes instead the way choices are presented. When employees are enrolled in a pension plan unless they choose to opt out, far more of them save than when they must opt in, though the choice is the same. Putting fruit at eye level in a canteen sells more fruit than a poster about healthy eating. Such ''nudges'' are cheap and leave people free to choose, which makes them attractive. But they work best where people already want the outcome and only inertia stands in the way. They do little when the problem is not inattention but poverty: a nudge to save means little to a family that has nothing left at the end of the month.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सरकारें लंबे समय से क़ानूनों और करों से व्यवहार बदलती रही हैं। एक नया तरीका इसके बजाय विकल्पों को प्रस्तुत करने का ढंग बदलता है। जब कर्मचारियों को पेंशन योजना में तब तक शामिल माना जाता है जब तक वे स्वयं बाहर निकलना न चुनें, तो उनमें से कहीं अधिक बचत करते हैं, बनिस्बत उस स्थिति के जब उन्हें स्वयं शामिल होना पड़ता है, यद्यपि विकल्प वही है। कैंटीन में फल आँखों की ऊँचाई पर रखने से स्वस्थ भोजन के पोस्टर की तुलना में अधिक फल बिकते हैं। ऐसे ''नज'' (हल्के प्रेरक संकेत) सस्ते हैं और लोगों को चुनने की स्वतंत्रता देते हैं, जिससे वे आकर्षक लगते हैं। पर वे वहाँ सबसे अच्छा काम करते हैं जहाँ लोग पहले से वही परिणाम चाहते हैं और केवल जड़ता रास्ते में है। जब समस्या असावधानी नहीं बल्कि ग़रीबी हो, तब वे बहुत कम कर पाते हैं: बचत का नज उस परिवार के लिए कुछ ख़ास मायने नहीं रखता जिसके पास महीने के अंत में कुछ बचता ही नहीं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Making saving the default can raise saving without forcing anyone to save.", "A nudge to save is unlikely to help a family that has no money left over."], "statements_hi": ["बचत को डिफ़ॉल्ट विकल्प बनाना किसी को बचत के लिए विवश किए बिना बचत बढ़ा सकता है।", "बचत का नज उस परिवार की मदद करे, इसकी संभावना कम है जिसके पास कोई पैसा बचता ही नहीं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p08", "csat_order": 54}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. Employees enrolled unless they opt out save far more, ''though the choice is the same'', so a default can raise saving while leaving everyone free to opt out (1). Nudges ''do little when the problem is not inattention but poverty'', and a nudge to save means little to a family with nothing left over (2).','दोनों वैध हैं। जब तक बाहर न निकलें तब तक शामिल माने गए कर्मचारी कहीं अधिक बचत करते हैं, ''यद्यपि विकल्प वही है'', इसलिए डिफ़ॉल्ट विकल्प हर किसी को बाहर निकलने की स्वतंत्रता देते हुए बचत बढ़ा सकता है (1)। नज ''तब बहुत कम कर पाते हैं जब समस्या असावधानी नहीं बल्कि ग़रीबी हो'', और बचत का नज उस परिवार के लिए कुछ मायने नहीं रखता जिसके पास कुछ बचता ही नहीं (2)।','csat-l2-t03-rc-p08-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Governments have long changed behaviour with laws and taxes. A newer approach changes instead the way choices are presented. When employees are enrolled in a pension plan unless they choose to opt out, far more of them save than when they must opt in, though the choice is the same. Putting fruit at eye level in a canteen sells more fruit than a poster about healthy eating. Such ''nudges'' are cheap and leave people free to choose, which makes them attractive. But they work best where people already want the outcome and only inertia stands in the way. They do little when the problem is not inattention but poverty: a nudge to save means little to a family that has nothing left at the end of the month.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सरकारें लंबे समय से क़ानूनों और करों से व्यवहार बदलती रही हैं। एक नया तरीका इसके बजाय विकल्पों को प्रस्तुत करने का ढंग बदलता है। जब कर्मचारियों को पेंशन योजना में तब तक शामिल माना जाता है जब तक वे स्वयं बाहर निकलना न चुनें, तो उनमें से कहीं अधिक बचत करते हैं, बनिस्बत उस स्थिति के जब उन्हें स्वयं शामिल होना पड़ता है, यद्यपि विकल्प वही है। कैंटीन में फल आँखों की ऊँचाई पर रखने से स्वस्थ भोजन के पोस्टर की तुलना में अधिक फल बिकते हैं। ऐसे ''नज'' (हल्के प्रेरक संकेत) सस्ते हैं और लोगों को चुनने की स्वतंत्रता देते हैं, जिससे वे आकर्षक लगते हैं। पर वे वहाँ सबसे अच्छा काम करते हैं जहाँ लोग पहले से वही परिणाम चाहते हैं और केवल जड़ता रास्ते में है। जब समस्या असावधानी नहीं बल्कि ग़रीबी हो, तब वे बहुत कम कर पाते हैं: बचत का नज उस परिवार के लिए कुछ ख़ास मायने नहीं रखता जिसके पास महीने के अंत में कुछ बचता ही नहीं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p08", "csat_order": 55}'::jsonb,'[{"id": "a", "body": "Laws and taxes no longer change people''s behaviour, so governments must turn to nudges.", "body_hi": "क़ानून और कर अब लोगों का व्यवहार नहीं बदलते, इसलिए सरकारों को नज अपनाने होंगे।", "isCorrect": false}, {"id": "b", "body": "Posters about healthy eating work better than changing how food is displayed in a canteen.", "body_hi": "स्वस्थ भोजन के पोस्टर कैंटीन में भोजन रखने का ढंग बदलने से बेहतर काम करते हैं।", "isCorrect": false}, {"id": "c", "body": "Employees who are enrolled in pension plans automatically are forced to save their money.", "body_hi": "पेंशन योजनाओं में अपने-आप शामिल किए गए कर्मचारी अपना पैसा बचाने के लिए पूरी तरह विवश हैं।", "isCorrect": false}, {"id": "d", "body": "Nudges cheaply help people do what they already want but cannot make up for poverty.", "body_hi": "नज सस्ते में वह करवाते हैं जो लोग पहले से चाहते हैं, पर ग़रीबी की भरपाई नहीं कर सकते।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage presents nudges as cheap and freedom-preserving, effective where only inertia stands in the way, and of little use where poverty is the problem. It does not say that laws and taxes have stopped working; it says fruit at eye level sells more than a poster does; and employees enrolled by default can still opt out, so they are not forced to save.','परिच्छेद नज को सस्ता और स्वतंत्रता बनाए रखने वाला बताता है, जो वहाँ प्रभावी है जहाँ केवल जड़ता रास्ते में हो, और वहाँ कम उपयोगी जहाँ समस्या ग़रीबी हो। वह नहीं कहता कि क़ानूनों और करों ने काम करना बंद कर दिया है; वह कहता है कि आँखों की ऊँचाई पर रखे फल पोस्टर से अधिक बिकते हैं; और डिफ़ॉल्ट रूप से शामिल कर्मचारी अब भी बाहर निकल सकते हैं, इसलिए वे बचत के लिए विवश नहीं हैं।','csat-l2-t03-rc-p08-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: What is the value of x + y?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: x + y का मान क्या है?','{"statements": ["2x + 3y = 12", "4x + 6y = 24"], "statements_hi": ["2x + 3y = 12", "4x + 6y = 24"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 56}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": true}]'::jsonb,2.5,0.83,'Statement I is one equation in two unknowns: x = 0 and y = 4 give x + y = 4, while x = 6 and y = 0 give 6 -- not sufficient. Statement II is Statement I multiplied by 2, so it adds no information, and even together the two leave x + y open. The trap is to count two equations and conclude that two unknowns can be found.','कथन I दो अज्ञात राशियों वाला एक समीकरण है: x = 0 और y = 4 से x + y = 4 मिलता है, जबकि x = 6 और y = 0 से 6 -- पर्याप्त नहीं। कथन II, कथन I को 2 से गुणा करने पर बनता है, इसलिए वह कोई नई जानकारी नहीं देता, और दोनों साथ लेकर भी x + y अनिर्धारित रहता है। जाल यह है कि दो समीकरण गिनकर मान लिया जाए कि दोनों अज्ञात निकल आएँगे।','csat-l2-t03-qa-ds-same-equation-twice','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Is x greater than y? (x and y are real numbers.)','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या x, y से बड़ा है? (x और y वास्तविक संख्याएँ हैं।)','{"statements": ["x² > y²", "x + y > 0"], "statements_hi": ["x² > y²", "x + y > 0"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 57}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: x = 3, y = 1 gives yes, but x = -3, y = 1 also satisfies x² > y² and gives no -- not sufficient. Statement II alone: x = 2, y = 1 gives yes and x = 1, y = 2 gives no. Together: x² - y² = (x - y)(x + y) is positive and x + y is positive, so x - y must be positive, that is x > y -- sufficient. Each statement alone fails; both together answer the question.','कथन I अकेला: x = 3, y = 1 से उत्तर हाँ है, पर x = -3, y = 1 भी x² > y² को संतुष्ट करते हैं और उत्तर नहीं देते -- पर्याप्त नहीं। कथन II अकेला: x = 2, y = 1 से हाँ और x = 1, y = 2 से नहीं। दोनों साथ: x² - y² = (x - y)(x + y) धनात्मक है और x + y धनात्मक है, इसलिए x - y धनात्मक होना चाहिए, यानी x > y -- पर्याप्त। कोई भी कथन अकेला काफ़ी नहीं; दोनों साथ मिलकर प्रश्न का उत्तर देते हैं।','csat-l2-t03-qa-ds-is-x-greater-than-y','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Are there more than 40 students in the class?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या कक्षा में 40 से अधिक विद्यार्थी हैं?','{"statements": ["If 5 more students joined the class, it would have more than 45 students.", "The class has fewer than 50 students."], "statements_hi": ["यदि कक्षा में 5 और विद्यार्थी आ जाएँ, तो उसमें 45 से अधिक विद्यार्थी होंगे।", "कक्षा में 50 से कम विद्यार्थी हैं।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 58}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I: if n + 5 is more than 45, then n is more than 40 -- the answer is yes, from I alone. Statement II: fewer than 50 allows 45 students (yes) or 30 (no) -- not sufficient. So the question can be answered using I alone but not using II alone.','कथन I: यदि n + 5, 45 से अधिक है, तो n, 40 से अधिक है -- उत्तर हाँ है, केवल I से। कथन II: 50 से कम में 45 विद्यार्थी (हाँ) भी हो सकते हैं और 30 (नहीं) भी -- पर्याप्त नहीं। अतः प्रश्न का उत्तर केवल I से दिया जा सकता है, केवल II से नहीं।','csat-l2-t03-lr-ds-more-than-forty','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: In which direction is the school from Ramesh''s house?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: रमेश के घर से विद्यालय किस दिशा में है?','{"statements": ["The school is due north of the temple, and the temple is due north of the house.", "The market is due south of the school, and the house is due south of the market."], "statements_hi": ["विद्यालय मंदिर के ठीक उत्तर में है, और मंदिर घर के ठीक उत्तर में है।", "बाज़ार विद्यालय के ठीक दक्षिण में है, और घर बाज़ार के ठीक दक्षिण में है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 59}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": true}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I: going due north from the house you reach the temple and then the school, so the school is due north of the house. Statement II: going due north from the house you reach the market and then the school -- again due north. Either statement alone answers the question. The trap is to think that each statement fixes only part of the route, so that both are needed.','कथन I: घर से ठीक उत्तर जाने पर पहले मंदिर और फिर विद्यालय आता है, इसलिए विद्यालय घर के ठीक उत्तर में है। कथन II: घर से ठीक उत्तर जाने पर पहले बाज़ार और फिर विद्यालय आता है -- फिर से ठीक उत्तर। कोई भी एक कथन अकेले प्रश्न का उत्तर दे देता है। जाल यह सोचना है कि हर कथन रास्ते का केवल एक भाग बताता है, इसलिए दोनों चाहिए।','csat-l2-t03-lr-ds-school-due-north','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: In a certain code language, what is the code for ''sky''?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: एक निश्चित कूट भाषा में ''sky'' का कूट क्या है?','{"statements": ["''blue sky above'' is written as ''ka pa ta''.", "''sky is clear'' is written as ''na pa ri''."], "statements_hi": ["''blue sky above'' को ''ka pa ta'' लिखा जाता है।", "''sky is clear'' को ''na pa ri'' लिखा जाता है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 60}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Each sentence alone matches three words with three codes in an unknown order, so ''sky'' could be any of them. Together, ''sky'' is the only word common to both sentences and ''pa'' the only code common to both, so ''sky'' is ''pa''. A code need not keep the order of the words, which is why neither statement alone is enough.','हर वाक्य अकेले तीन शब्दों को तीन कूटों से किसी अज्ञात क्रम में मिलाता है, इसलिए ''sky'' उनमें से कोई भी हो सकता है। दोनों साथ: ''sky'' दोनों वाक्यों में अकेला साझा शब्द है और ''pa'' अकेला साझा कूट, इसलिए ''sky'' का कूट ''pa'' है। कूट में शब्दों का क्रम बना रहना ज़रूरी नहीं, इसीलिए कोई भी कथन अकेले पर्याप्त नहीं है।','csat-l2-t03-lr-ds-code-for-sky','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
As forests are cut into fragments by roads, canals and farms, elephants that once moved between them along old routes find their way blocked, and they walk instead through villages and fields. Each year crops are lost, homes damaged and people killed, and every death hardens attitudes towards the animals. Fences and trenches push elephants from one village to the next without reducing the conflict overall. The approach that has worked better treats the problem as one of movement: keeping open the corridors between forests, warning villages when a herd is near, and paying compensation quickly enough that farmers do not take matters into their own hands.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जैसे-जैसे सड़कें, नहरें और खेत जंगलों को टुकड़ों में बाँटते हैं, वे हाथी जो कभी पुराने रास्तों से एक जंगल से दूसरे तक जाते थे, अपना रास्ता बंद पाते हैं, और इसके बजाय गाँवों और खेतों से होकर गुज़रते हैं। हर वर्ष फ़सलें नष्ट होती हैं, घर टूटते हैं और लोग मारे जाते हैं, और हर मौत इन जानवरों के प्रति रवैये को और कठोर बना देती है। बाड़ और खाइयाँ हाथियों को एक गाँव से अगले गाँव की ओर धकेल देती हैं, पर कुल मिलाकर संघर्ष नहीं घटातीं। जिस तरीके ने बेहतर काम किया है, वह समस्या को आवाजाही की समस्या मानता है: जंगलों के बीच के गलियारों को खुला रखना, झुंड पास होने पर गाँवों को चेतावनी देना, और मुआवज़ा इतनी जल्दी देना कि किसान मामला अपने हाथ में न लें।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p09", "csat_order": 61}'::jsonb,'[{"id": "a", "body": "Elephants are by nature aggressive towards the people who live near the forests.", "body_hi": "हाथी स्वभाव से ही जंगलों के पास रहने वाले लोगों के प्रति आक्रामक होते हैं।", "isCorrect": false}, {"id": "b", "body": "Conflict with elephants eases when their routes between forests are kept open.", "body_hi": "जंगलों के बीच हाथियों के रास्ते खुले रखने पर उनसे संघर्ष घटता है।", "isCorrect": true}, {"id": "c", "body": "Fences and trenches are the best way to keep elephants out of villages and fields.", "body_hi": "हाथियों को गाँवों और खेतों से बाहर रखने का सबसे अच्छा तरीका बाड़ और खाइयाँ हैं।", "isCorrect": false}, {"id": "d", "body": "Farmers whose fields lie near forests should be moved out to protect the elephants.", "body_hi": "जिन किसानों के खेत जंगलों के पास हैं, उन्हें हाथियों की रक्षा के लिए वहाँ से हटा देना चाहिए।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage traces the conflict to blocked routes between fragmented forests, and says the approach that has worked better treats it as a problem of movement -- open corridors, warnings and quick compensation. It never calls elephants aggressive by nature; it says fences and trenches only move the problem on; and it does not propose moving farmers out.','परिच्छेद संघर्ष को टुकड़ों में बँटे जंगलों के बीच बंद रास्तों से जोड़ता है, और कहता है कि जिस तरीके ने बेहतर काम किया वह इसे आवाजाही की समस्या मानता है -- खुले गलियारे, चेतावनियाँ और जल्दी मुआवज़ा। वह हाथियों को स्वभाव से आक्रामक कभी नहीं कहता; वह कहता है कि बाड़ और खाइयाँ समस्या को केवल आगे सरका देती हैं; और वह किसानों को हटाने का प्रस्ताव नहीं करता।','csat-l2-t03-rc-p09-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
As forests are cut into fragments by roads, canals and farms, elephants that once moved between them along old routes find their way blocked, and they walk instead through villages and fields. Each year crops are lost, homes damaged and people killed, and every death hardens attitudes towards the animals. Fences and trenches push elephants from one village to the next without reducing the conflict overall. The approach that has worked better treats the problem as one of movement: keeping open the corridors between forests, warning villages when a herd is near, and paying compensation quickly enough that farmers do not take matters into their own hands.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जैसे-जैसे सड़कें, नहरें और खेत जंगलों को टुकड़ों में बाँटते हैं, वे हाथी जो कभी पुराने रास्तों से एक जंगल से दूसरे तक जाते थे, अपना रास्ता बंद पाते हैं, और इसके बजाय गाँवों और खेतों से होकर गुज़रते हैं। हर वर्ष फ़सलें नष्ट होती हैं, घर टूटते हैं और लोग मारे जाते हैं, और हर मौत इन जानवरों के प्रति रवैये को और कठोर बना देती है। बाड़ और खाइयाँ हाथियों को एक गाँव से अगले गाँव की ओर धकेल देती हैं, पर कुल मिलाकर संघर्ष नहीं घटातीं। जिस तरीके ने बेहतर काम किया है, वह समस्या को आवाजाही की समस्या मानता है: जंगलों के बीच के गलियारों को खुला रखना, झुंड पास होने पर गाँवों को चेतावनी देना, और मुआवज़ा इतनी जल्दी देना कि किसान मामला अपने हाथ में न लें।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Fences and trenches have reduced the conflict between people and elephants overall.", "Slow payment of compensation can make farmers more likely to harm elephants."], "statements_hi": ["बाड़ और खाइयों ने कुल मिलाकर लोगों और हाथियों के बीच संघर्ष घटाया है।", "मुआवज़े के भुगतान में देरी किसानों द्वारा हाथियों को हानि पहुँचाने की संभावना बढ़ा सकती है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p09", "csat_order": 62}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. Compensation must be paid ''quickly enough that farmers do not take matters into their own hands'', which implies that slow payment makes them likelier to act against the animals (2). 1 contradicts the passage: fences and trenches move elephants on ''without reducing the conflict overall''.','केवल 2 वैध है। मुआवज़ा ''इतनी जल्दी देना कि किसान मामला अपने हाथ में न लें'', इसका अर्थ है कि भुगतान में देरी उन्हें जानवरों के विरुद्ध कदम उठाने की ओर अधिक ले जाती है (2)। 1 परिच्छेद का खंडन करता है: बाड़ और खाइयाँ हाथियों को आगे धकेलती हैं, ''पर कुल मिलाकर संघर्ष नहीं घटातीं''।','csat-l2-t03-rc-p09-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
As forests are cut into fragments by roads, canals and farms, elephants that once moved between them along old routes find their way blocked, and they walk instead through villages and fields. Each year crops are lost, homes damaged and people killed, and every death hardens attitudes towards the animals. Fences and trenches push elephants from one village to the next without reducing the conflict overall. The approach that has worked better treats the problem as one of movement: keeping open the corridors between forests, warning villages when a herd is near, and paying compensation quickly enough that farmers do not take matters into their own hands.

According to the passage, which of the following have cut the forests into fragments?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जैसे-जैसे सड़कें, नहरें और खेत जंगलों को टुकड़ों में बाँटते हैं, वे हाथी जो कभी पुराने रास्तों से एक जंगल से दूसरे तक जाते थे, अपना रास्ता बंद पाते हैं, और इसके बजाय गाँवों और खेतों से होकर गुज़रते हैं। हर वर्ष फ़सलें नष्ट होती हैं, घर टूटते हैं और लोग मारे जाते हैं, और हर मौत इन जानवरों के प्रति रवैये को और कठोर बना देती है। बाड़ और खाइयाँ हाथियों को एक गाँव से अगले गाँव की ओर धकेल देती हैं, पर कुल मिलाकर संघर्ष नहीं घटातीं। जिस तरीके ने बेहतर काम किया है, वह समस्या को आवाजाही की समस्या मानता है: जंगलों के बीच के गलियारों को खुला रखना, झुंड पास होने पर गाँवों को चेतावनी देना, और मुआवज़ा इतनी जल्दी देना कि किसान मामला अपने हाथ में न लें।

परिच्छेद के अनुसार, निम्नलिखित में से किन्होंने जंगलों को टुकड़ों में बाँटा है?','{"craft": "precision", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p09", "csat_order": 63}'::jsonb,'[{"id": "a", "body": "fences and trenches put up around villages", "body_hi": "गाँवों के चारों ओर बनी बाड़ और खाइयाँ", "isCorrect": false}, {"id": "b", "body": "the herds of elephants that move between them", "body_hi": "उनके बीच घूमने वाले हाथियों के झुंड", "isCorrect": false}, {"id": "c", "body": "roads, canals and farms", "body_hi": "सड़कें, नहरें और खेत", "isCorrect": true}, {"id": "d", "body": "warnings sent to villages when a herd is near", "body_hi": "झुंड पास होने पर गाँवों को भेजी गई चेतावनियाँ", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says that forests are ''cut into fragments by roads, canals and farms''. Fences and trenches push elephants from village to village but are not said to fragment the forests; the herds are what the fragmenting blocks; and warnings to villages are part of the remedy.','परिच्छेद कहता है कि जंगल ''सड़कों, नहरों और खेतों'' से टुकड़ों में बँटते हैं। बाड़ और खाइयाँ हाथियों को गाँव-दर-गाँव धकेलती हैं, पर उनके बारे में यह नहीं कहा गया कि वे जंगलों को बाँटती हैं; झुंड वे हैं जिनका रास्ता यह बँटवारा रोकता है; और गाँवों को चेतावनी उपाय का भाग है।','csat-l2-t03-rc-p09-detail','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','medium','In how many ways can 3 different prizes be given to 5 students, if a student may receive more than one prize?','3 अलग-अलग पुरस्कार 5 विद्यार्थियों को कितने तरीकों से दिए जा सकते हैं, यदि एक विद्यार्थी एक से अधिक पुरस्कार पा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 64}'::jsonb,'[{"id": "a", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "b", "body": "60", "body_hi": "60", "isCorrect": false}, {"id": "c", "body": "125", "body_hi": "125", "isCorrect": true}, {"id": "d", "body": "243", "body_hi": "243", "isCorrect": false}]'::jsonb,2.5,0.83,'Each of the 3 prizes can go to any of the 5 students, independently of the others: 5 × 5 × 5 = 125. 60 = 5 × 4 × 3 would hold if no student could get two prizes; 243 = 3⁵ reverses the roles, as if each student chose a prize; 15 = 5 × 3 only counts student-prize pairs.','3 में से हर पुरस्कार 5 में से किसी भी विद्यार्थी को, दूसरों से स्वतंत्र रूप से, जा सकता है: 5 × 5 × 5 = 125। 60 = 5 × 4 × 3 तब सही होता जब कोई विद्यार्थी दो पुरस्कार न पा सकता; 243 = 3⁵ भूमिकाएँ उलट देता है, मानो हर विद्यार्थी एक पुरस्कार चुनता हो; 15 = 5 × 3 केवल विद्यार्थी-पुरस्कार जोड़ियाँ गिनता है।','csat-l2-t03-qa-pc-prizes-with-repeats','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','hard','Pointing to a photograph, a man says, ''She is the only daughter of the father of my brother''s wife''s husband.'' How is the woman in the photograph related to the man?','एक तस्वीर की ओर इशारा करते हुए एक पुरुष कहता है, ''वह मेरे भाई की पत्नी के पति के पिता की इकलौती बेटी है।'' तस्वीर वाली महिला उस पुरुष की क्या लगती है?','{"craft": "inference", "csat_set": "csat-l2-t03", "csat_order": 65}'::jsonb,'[{"id": "a", "body": "Sister-in-law", "body_hi": "भाभी", "isCorrect": false}, {"id": "b", "body": "Mother", "body_hi": "माँ", "isCorrect": false}, {"id": "c", "body": "Cousin", "body_hi": "चचेरी बहन", "isCorrect": false}, {"id": "d", "body": "Sister", "body_hi": "बहन", "isCorrect": true}]'::jsonb,2.5,0.83,'Unwind it from the inside. The man''s brother''s wife''s husband is the brother himself; the father of his brother is the man''s own father; and the only daughter of his father is his sister. ''Sister-in-law'' stops at the brother''s wife and forgets that her husband brings the chain back to the man''s own family; ''mother'' is his father''s wife, not his daughter; a cousin would have a different father.','भीतर से खोलिए। पुरुष के भाई की पत्नी का पति स्वयं वह भाई है; भाई के पिता पुरुष के अपने पिता हैं; और पिता की इकलौती बेटी उसकी बहन है। ''भाभी'' भाई की पत्नी पर रुक जाता है और भूल जाता है कि उसका पति शृंखला को पुरुष के अपने परिवार में लौटा देता है; ''माँ'' पिता की पत्नी है, बेटी नहीं; चचेरी बहन के पिता अलग होते।','csat-l2-t03-lr-br-chain-folds-back','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','hard','The sides of a triangle are 7 cm, 24 cm and 25 cm. What is the radius of the circle that touches all three of its sides?','एक त्रिभुज की भुजाएँ 7 सेमी, 24 सेमी और 25 सेमी हैं। उसकी तीनों भुजाओं को स्पर्श करने वाले वृत्त की त्रिज्या क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 66}'::jsonb,'[{"id": "a", "body": "3 cm", "body_hi": "3 सेमी", "isCorrect": true}, {"id": "b", "body": "3.5 cm", "body_hi": "3.5 सेमी", "isCorrect": false}, {"id": "c", "body": "6 cm", "body_hi": "6 सेमी", "isCorrect": false}, {"id": "d", "body": "12.5 cm", "body_hi": "12.5 सेमी", "isCorrect": false}]'::jsonb,2.5,0.83,'7² + 24² = 49 + 576 = 625 = 25², so the triangle is right-angled, with area ½ × 7 × 24 = 84 cm². The radius of the inscribed circle is area ÷ semi-perimeter = 84 ÷ 28 = 3 cm (for a right triangle it is also (7 + 24 - 25)/2 = 3). 12.5 cm is the radius of the circle through the corners, half the hypotenuse; 6 cm is the diameter of the inscribed circle; 3.5 cm is half the shortest side.','7² + 24² = 49 + 576 = 625 = 25², इसलिए त्रिभुज समकोण है, जिसका क्षेत्रफल ½ × 7 × 24 = 84 वर्ग सेमी है। अंतःवृत्त की त्रिज्या = क्षेत्रफल ÷ अर्धपरिमाप = 84 ÷ 28 = 3 सेमी (समकोण त्रिभुज में यह (7 + 24 - 25)/2 = 3 भी है)। 12.5 सेमी शीर्षों से होकर जाने वाले वृत्त की त्रिज्या है, कर्ण का आधा; 6 सेमी अंतःवृत्त का व्यास है; 3.5 सेमी सबसे छोटी भुजा का आधा है।','csat-l2-t03-qa-gm-incircle-7-24-25','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','hard','A can finish a job in 6 days and B in 12 days. They work on alternate days, A on the first day, B on the second, and so on. In how many days will the job be finished?','A किसी काम को 6 दिनों में और B 12 दिनों में पूरा कर सकता है। वे बारी-बारी से एक-एक दिन काम करते हैं, पहले दिन A, दूसरे दिन B, और इसी प्रकार आगे। काम कितने दिनों में पूरा होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 67}'::jsonb,'[{"id": "a", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "b", "body": "7½", "body_hi": "7½", "isCorrect": false}, {"id": "c", "body": "8", "body_hi": "8", "isCorrect": true}, {"id": "d", "body": "12", "body_hi": "12", "isCorrect": false}]'::jsonb,2.5,0.83,'In each pair of days A does 1/6 and B 1/12, together 1/4. After 6 days, three pairs, 3/4 is done; on day 7 A adds 1/6, making 11/12; the last 1/12 is exactly one day of B''s work, so the job ends with day 8. 4 days is the time if both worked every day; 7½ gives day 8 to A, forgetting that it is B''s turn; 12 is B''s time working alone.','हर दो दिनों में A, 1/6 और B, 1/12 काम करता है, मिलकर 1/4। 6 दिनों, यानी तीन जोड़ियों, के बाद 3/4 काम हो जाता है; सातवें दिन A, 1/6 जोड़कर इसे 11/12 कर देता है; शेष 1/12 ठीक B का एक दिन का काम है, इसलिए काम आठवें दिन पूरा होता है। 4 दिन तब लगते जब दोनों हर दिन काम करते; 7½, आठवाँ दिन A को दे देता है, यह भूलकर कि वह B की बारी है; 12, B का अकेले काम करने का समय है।','csat-l2-t03-qa-tw-alternate-days','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','medium','Town X lies due south-west of town Y. Town Z lies due east of X and due south of Y. In which direction is Y from Z?','कस्बा X, कस्बे Y के ठीक दक्षिण-पश्चिम में है। कस्बा Z, X के ठीक पूर्व में और Y के ठीक दक्षिण में है। Z से Y किस दिशा में है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 68}'::jsonb,'[{"id": "a", "body": "North", "body_hi": "उत्तर", "isCorrect": true}, {"id": "b", "body": "North-east", "body_hi": "उत्तर-पूर्व", "isCorrect": false}, {"id": "c", "body": "East", "body_hi": "पूर्व", "isCorrect": false}, {"id": "d", "body": "North-west", "body_hi": "उत्तर-पश्चिम", "isCorrect": false}]'::jsonb,2.5,0.83,'Put Y at the centre. X is south-west of Y -- say a km west and a km south of it. Z is due east of X, so it is also a km south of Y, and it is due south of Y, so it lies directly below Y. Y is therefore due north of Z. North-east is the direction of Y from X; east is the direction of Z from X; north-west would need Z to lie to the east of Y.','Y को केंद्र में रखिए। X, Y के दक्षिण-पश्चिम में है -- मान लीजिए उससे a किमी पश्चिम और a किमी दक्षिण। Z, X के ठीक पूर्व में है, इसलिए वह भी Y से a किमी दक्षिण में है, और वह Y के ठीक दक्षिण में है, इसलिए Y के ठीक नीचे है। अतः Y, Z के ठीक उत्तर में है। उत्तर-पूर्व, X से Y की दिशा है; पूर्व, X से Z की दिशा है; उत्तर-पश्चिम के लिए Z को Y के पूर्व में होना चाहिए था।','csat-l2-t03-lr-dd-towns-without-distances','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Best Summary','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Gross domestic product measures the value of what an economy produces in a year, and it does this well. The trouble begins when it is taken for a measure of how well people live. GDP rises when a forest is felled and its timber sold, but does not fall to reflect the loss of the forest. It counts the cost of treating illness caused by polluted air as output. And it leaves out the unpaid work of caring for children and the old, which would be a large part of the economy if anyone were paid for it. None of this means GDP should be dropped; growth still pays for schools and hospitals. It means that a country which watches only GDP may grow richer on paper while some of what matters to its people declines.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सकल घरेलू उत्पाद (GDP) किसी अर्थव्यवस्था द्वारा एक वर्ष में उत्पादित वस्तुओं और सेवाओं का मूल्य मापता है, और यह काम वह अच्छी तरह करता है। कठिनाई तब शुरू होती है जब उसे इस बात का माप मान लिया जाता है कि लोग कितनी अच्छी तरह जीते हैं। जब कोई जंगल काटा जाता है और उसकी लकड़ी बेची जाती है तो GDP बढ़ता है, पर जंगल की हानि दर्शाने के लिए घटता नहीं। प्रदूषित हवा से हुई बीमारी के इलाज की लागत को वह उत्पादन गिनता है। और वह बच्चों और बुज़ुर्गों की देखभाल के बिना वेतन वाले काम को छोड़ देता है, जो अर्थव्यवस्था का बड़ा भाग होता यदि किसी को उसके लिए वेतन मिलता। इसका अर्थ यह नहीं कि GDP को छोड़ दिया जाए; वृद्धि अब भी विद्यालयों और अस्पतालों का ख़र्च उठाती है। इसका अर्थ यह है कि जो देश केवल GDP पर नज़र रखता है, वह काग़ज़ पर अमीर होता जा सकता है जबकि उसके लोगों के लिए महत्त्वपूर्ण कुछ चीज़ें घटती जाएँ।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p10", "csat_order": 69}'::jsonb,'[{"id": "a", "body": "GDP measures output well but misleads if it is taken alone as a measure of wellbeing.", "body_hi": "GDP उत्पादन अच्छी तरह मापता है, पर अकेले कल्याण का माप मान लेने पर भ्रम पैदा करता है।", "isCorrect": true}, {"id": "b", "body": "GDP should be dropped altogether and replaced by a measure of how happy people say they are.", "body_hi": "GDP को पूरी तरह छोड़कर उसकी जगह इस बात का माप अपनाना चाहिए कि लोग स्वयं को कितना सुखी बताते हैं।", "isCorrect": false}, {"id": "c", "body": "Economic growth does not pay for public services such as schools and hospitals.", "body_hi": "आर्थिक वृद्धि विद्यालयों और अस्पतालों जैसी सार्वजनिक सेवाओं का ख़र्च नहीं उठाती।", "isCorrect": false}, {"id": "d", "body": "The unpaid work of caring for children and the old is already counted in GDP.", "body_hi": "बच्चों और बुज़ुर्गों की देखभाल का बिना वेतन वाला काम पहले से GDP में गिना जाता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage grants that GDP measures output well, shows three ways in which it misjudges wellbeing, and concludes that a country watching only GDP can grow richer on paper while losing what matters. It says GDP should not be dropped; it says growth still pays for schools and hospitals; and it says unpaid care is left out of GDP, not counted in it.','परिच्छेद मानता है कि GDP उत्पादन को अच्छी तरह मापता है, तीन ऐसे तरीके दिखाता है जिनसे वह कल्याण को ग़लत आँकता है, और निष्कर्ष निकालता है कि केवल GDP पर नज़र रखने वाला देश काग़ज़ पर अमीर होते हुए भी महत्त्वपूर्ण चीज़ें खो सकता है। वह कहता है कि GDP को छोड़ा नहीं जाना चाहिए; वह कहता है कि वृद्धि अब भी विद्यालयों और अस्पतालों का ख़र्च उठाती है; और वह कहता है कि बिना वेतन की देखभाल GDP से बाहर है, उसमें गिनी नहीं जाती।','csat-l2-t03-rc-p10-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Gross domestic product measures the value of what an economy produces in a year, and it does this well. The trouble begins when it is taken for a measure of how well people live. GDP rises when a forest is felled and its timber sold, but does not fall to reflect the loss of the forest. It counts the cost of treating illness caused by polluted air as output. And it leaves out the unpaid work of caring for children and the old, which would be a large part of the economy if anyone were paid for it. None of this means GDP should be dropped; growth still pays for schools and hospitals. It means that a country which watches only GDP may grow richer on paper while some of what matters to its people declines.

According to the passage, which one of the following does GDP leave out?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सकल घरेलू उत्पाद (GDP) किसी अर्थव्यवस्था द्वारा एक वर्ष में उत्पादित वस्तुओं और सेवाओं का मूल्य मापता है, और यह काम वह अच्छी तरह करता है। कठिनाई तब शुरू होती है जब उसे इस बात का माप मान लिया जाता है कि लोग कितनी अच्छी तरह जीते हैं। जब कोई जंगल काटा जाता है और उसकी लकड़ी बेची जाती है तो GDP बढ़ता है, पर जंगल की हानि दर्शाने के लिए घटता नहीं। प्रदूषित हवा से हुई बीमारी के इलाज की लागत को वह उत्पादन गिनता है। और वह बच्चों और बुज़ुर्गों की देखभाल के बिना वेतन वाले काम को छोड़ देता है, जो अर्थव्यवस्था का बड़ा भाग होता यदि किसी को उसके लिए वेतन मिलता। इसका अर्थ यह नहीं कि GDP को छोड़ दिया जाए; वृद्धि अब भी विद्यालयों और अस्पतालों का ख़र्च उठाती है। इसका अर्थ यह है कि जो देश केवल GDP पर नज़र रखता है, वह काग़ज़ पर अमीर होता जा सकता है जबकि उसके लोगों के लिए महत्त्वपूर्ण कुछ चीज़ें घटती जाएँ।

परिच्छेद के अनुसार, GDP निम्नलिखित में से किसे छोड़ देता है?','{"craft": "precision", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p10", "csat_order": 70}'::jsonb,'[{"id": "a", "body": "the value of timber from a forest that is felled", "body_hi": "काटे गए जंगल से मिली लकड़ी का मूल्य", "isCorrect": false}, {"id": "b", "body": "the cost of treating illness caused by polluted air", "body_hi": "प्रदूषित हवा से हुई बीमारी के इलाज की लागत", "isCorrect": false}, {"id": "c", "body": "the money that growth provides for schools and hospitals", "body_hi": "वृद्धि से विद्यालयों और अस्पतालों के लिए मिलने वाला धन", "isCorrect": false}, {"id": "d", "body": "the unpaid work of caring for children and the old", "body_hi": "बच्चों और बुज़ुर्गों की देखभाल का बिना वेतन वाला काम", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage says GDP ''leaves out the unpaid work of caring for children and the old''. The timber of a felled forest is counted -- GDP rises when it is sold; the cost of treating illness caused by polluted air is counted as output; and the passage says growth pays for schools and hospitals, not that GDP leaves that spending out.','परिच्छेद कहता है कि GDP ''बच्चों और बुज़ुर्गों की देखभाल के बिना वेतन वाले काम को छोड़ देता है''। काटे गए जंगल की लकड़ी गिनी जाती है -- उसके बिकने पर GDP बढ़ता है; प्रदूषित हवा से हुई बीमारी के इलाज की लागत उत्पादन के रूप में गिनी जाती है; और परिच्छेद कहता है कि वृद्धि विद्यालयों और अस्पतालों का ख़र्च उठाती है, यह नहीं कि GDP उस ख़र्च को छोड़ देता है।','csat-l2-t03-rc-p10-detail','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Gross domestic product measures the value of what an economy produces in a year, and it does this well. The trouble begins when it is taken for a measure of how well people live. GDP rises when a forest is felled and its timber sold, but does not fall to reflect the loss of the forest. It counts the cost of treating illness caused by polluted air as output. And it leaves out the unpaid work of caring for children and the old, which would be a large part of the economy if anyone were paid for it. None of this means GDP should be dropped; growth still pays for schools and hospitals. It means that a country which watches only GDP may grow richer on paper while some of what matters to its people declines.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सकल घरेलू उत्पाद (GDP) किसी अर्थव्यवस्था द्वारा एक वर्ष में उत्पादित वस्तुओं और सेवाओं का मूल्य मापता है, और यह काम वह अच्छी तरह करता है। कठिनाई तब शुरू होती है जब उसे इस बात का माप मान लिया जाता है कि लोग कितनी अच्छी तरह जीते हैं। जब कोई जंगल काटा जाता है और उसकी लकड़ी बेची जाती है तो GDP बढ़ता है, पर जंगल की हानि दर्शाने के लिए घटता नहीं। प्रदूषित हवा से हुई बीमारी के इलाज की लागत को वह उत्पादन गिनता है। और वह बच्चों और बुज़ुर्गों की देखभाल के बिना वेतन वाले काम को छोड़ देता है, जो अर्थव्यवस्था का बड़ा भाग होता यदि किसी को उसके लिए वेतन मिलता। इसका अर्थ यह नहीं कि GDP को छोड़ दिया जाए; वृद्धि अब भी विद्यालयों और अस्पतालों का ख़र्च उठाती है। इसका अर्थ यह है कि जो देश केवल GDP पर नज़र रखता है, वह काग़ज़ पर अमीर होता जा सकता है जबकि उसके लोगों के लिए महत्त्वपूर्ण कुछ चीज़ें घटती जाएँ।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["How well people live depends on more than the value of what their economy produces.", "A forest has a value that is lost when it is felled, even if its timber is sold."], "statements_hi": ["लोग कितनी अच्छी तरह जीते हैं, यह उनकी अर्थव्यवस्था के उत्पादन के मूल्य से अधिक बातों पर निर्भर करता है।", "जंगल का ऐसा मूल्य होता है जो उसके काटे जाने पर खो जाता है, भले उसकी लकड़ी बेच दी जाए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l2-t03", "passage_group": "csat-l2-t03-p10", "csat_order": 71}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are assumed. The complaint that GDP is a poor measure of ''how well people live'' takes for granted that wellbeing depends on more than output (1). Saying that GDP ''does not fall to reflect the loss of the forest'' assumes that the standing forest had a value beyond the timber that was sold (2).','दोनों पूर्वधारणाएँ हैं। यह शिकायत कि GDP इस बात का कमज़ोर माप है कि ''लोग कितनी अच्छी तरह जीते हैं'', मानकर चलती है कि कल्याण उत्पादन से अधिक पर निर्भर है (1)। यह कहना कि GDP ''जंगल की हानि दर्शाने के लिए घटता नहीं'', मानता है कि खड़े जंगल का मूल्य बेची गई लकड़ी से अधिक था (2)।','csat-l2-t03-rc-p10-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','The digits of a two-digit number add up to 9. When the digits are reversed, the number decreases by 27. What is the number?','दो अंकों की एक संख्या के अंकों का योग 9 है। अंकों को उलटने पर संख्या 27 घट जाती है। संख्या क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 72}'::jsonb,'[{"id": "a", "body": "36", "body_hi": "36", "isCorrect": false}, {"id": "b", "body": "45", "body_hi": "45", "isCorrect": false}, {"id": "c", "body": "54", "body_hi": "54", "isCorrect": false}, {"id": "d", "body": "63", "body_hi": "63", "isCorrect": true}]'::jsonb,2.5,0.83,'Write the number as 10a + b. Reversed, it is 10b + a, and the fall is 9(a - b) = 27, so a - b = 3. With a + b = 9, a = 6 and b = 3: the number is 63, and 63 - 36 = 27. 36 is the reversed number, which would increase by 27; 54 and 45 have digits adding up to 9 but change by only 9 when reversed.','संख्या को 10a + b लिखिए। उलटने पर वह 10b + a है, और कमी 9(a - b) = 27 है, अतः a - b = 3। a + b = 9 के साथ a = 6 और b = 3: संख्या 63 है, और 63 - 36 = 27। 36 उलटी संख्या है, जो 27 बढ़ जाती; 54 और 45 के अंकों का योग 9 है, पर उलटने पर वे केवल 9 बदलती हैं।','csat-l2-t03-qa-nt-digits-reversed-27','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','hard','A man saves 20% of his income. His income then rises by 20% and his expenditure by 25%. What happens to his savings?','एक व्यक्ति अपनी आय का 20% बचाता है। फिर उसकी आय 20% और उसका व्यय 25% बढ़ जाता है। उसकी बचत का क्या होता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 73}'::jsonb,'[{"id": "a", "body": "They fall by 5%", "body_hi": "वह 5% घटती है", "isCorrect": false}, {"id": "b", "body": "They stay the same", "body_hi": "वह उतनी ही रहती है", "isCorrect": true}, {"id": "c", "body": "They rise by 5%", "body_hi": "वह 5% बढ़ती है", "isCorrect": false}, {"id": "d", "body": "They rise by 20%", "body_hi": "वह 20% बढ़ती है", "isCorrect": false}]'::jsonb,2.5,0.83,'Take his income as 100: he spends 80 and saves 20. Afterwards he earns 120 and spends 80 × 1.25 = 100, so he still saves 20 -- no change. The two rates apply to different bases: 25% of 80 is the same amount as 20% of 100. ''Fall by 5%'' subtracts one rate from the other (20 - 25); ''rise by 20%'' assumes savings move with income; a 5% rise has no basis at all.','उसकी आय 100 मानिए: वह 80 ख़र्च करता और 20 बचाता है। बाद में वह 120 कमाता है और 80 × 1.25 = 100 ख़र्च करता है, इसलिए वह अब भी 20 बचाता है -- कोई बदलाव नहीं। दोनों दरें अलग-अलग आधारों पर लगती हैं: 80 का 25% उतनी ही राशि है जितनी 100 का 20%। ''5% घटती है'' एक दर में से दूसरी घटा देता है (20 - 25); ''20% बढ़ती है'' मान लेता है कि बचत आय के साथ चलती है; 5% की वृद्धि का कोई आधार ही नहीं।','csat-l2-t03-qa-pp-savings-unchanged','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','medium','If ''+'' means ''×'', ''-'' means ''+'', ''×'' means ''÷'' and ''÷'' means ''-'', what is the value of 8 + 6 - 4 ÷ 12 × 3?','यदि ''+'' का अर्थ ''×'', ''-'' का अर्थ ''+'', ''×'' का अर्थ ''÷'' और ''÷'' का अर्थ ''-'' हो, तो 8 + 6 - 4 ÷ 12 × 3 का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 74}'::jsonb,'[{"id": "a", "body": "16", "body_hi": "16", "isCorrect": false}, {"id": "b", "body": "40", "body_hi": "40", "isCorrect": false}, {"id": "c", "body": "48", "body_hi": "48", "isCorrect": true}, {"id": "d", "body": "56", "body_hi": "56", "isCorrect": false}]'::jsonb,2.5,0.83,'Rewrite with the true signs: 8 × 6 + 4 - 12 ÷ 3. Doing division and multiplication first, 48 + 4 - 4 = 48. 16 forgets that × stands for ÷ (it subtracts 12 × 3 = 36); 40 leaves the ''-'' as a minus sign; 56 turns the ÷ into + instead of -.','सही चिह्नों के साथ फिर लिखिए: 8 × 6 + 4 - 12 ÷ 3। पहले भाग और गुणा करने पर 48 + 4 - 4 = 48। 16 भूल जाता है कि × का अर्थ ÷ है (वह 12 × 3 = 36 घटाता है); 40, ''-'' को घटाने का चिह्न ही रहने देता है; 56, ÷ को - के बजाय + बना देता है।','csat-l2-t03-lr-cd-swapped-operators','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','Excluding stoppages, a bus runs at 54 km/h; including stoppages, its average speed is 45 km/h. For how many minutes in each hour does the bus stop?','ठहराव को छोड़कर एक बस 54 किमी/घंटा की चाल से चलती है; ठहराव सहित उसकी औसत चाल 45 किमी/घंटा है। बस हर घंटे कितने मिनट रुकती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 75}'::jsonb,'[{"id": "a", "body": "9", "body_hi": "9", "isCorrect": false}, {"id": "b", "body": "10", "body_hi": "10", "isCorrect": true}, {"id": "c", "body": "12", "body_hi": "12", "isCorrect": false}, {"id": "d", "body": "15", "body_hi": "15", "isCorrect": false}]'::jsonb,2.5,0.83,'In each hour the bus covers 45 km instead of 54 km, so it loses the time it would need for 9 km at its running speed: 9/54 of an hour, or 10 minutes. 9 reads the 9 km/h lost as minutes; 12 divides the loss by 45 instead of 54; 15 assumes the bus moves for 45 minutes because its average speed is 45.','हर घंटे बस 54 किमी के बजाय 45 किमी तय करती है, इसलिए वह उतना समय खोती है जितना उसे अपनी चलने की चाल से 9 किमी तय करने में लगता: घंटे का 9/54 भाग, यानी 10 मिनट। 9 खोए गए 9 किमी/घंटा को मिनट मान लेता है; 12 कमी को 54 के बजाय 45 से भाग देता है; 15 मान लेता है कि बस 45 मिनट चलती है क्योंकि उसकी औसत चाल 45 है।','csat-l2-t03-qa-sdt-bus-stoppage-minutes','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','A is now twice as old as B was when A was as old as B is now. The sum of their present ages is 63 years. What is A''s present age in years?','A की वर्तमान आयु उस समय की B की आयु की दोगुनी है जब A की आयु उतनी थी जितनी अब B की है। दोनों की वर्तमान आयु का योग 63 वर्ष है। A की वर्तमान आयु कितने वर्ष है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 76}'::jsonb,'[{"id": "a", "body": "18", "body_hi": "18", "isCorrect": false}, {"id": "b", "body": "27", "body_hi": "27", "isCorrect": false}, {"id": "c", "body": "36", "body_hi": "36", "isCorrect": true}, {"id": "d", "body": "42", "body_hi": "42", "isCorrect": false}]'::jsonb,2.5,0.83,'Let A be a and B be b years old now, with a > b. A was b years old a - b years ago, when B was b - (a - b) = 2b - a. So a = 2(2b - a), that is 3a = 4b, and with a + b = 63, b = 27 and a = 36. Check: nine years ago A was 27 and B was 18, and 36 is twice 18. 42 takes A as simply twice B''s present age; 27 is B''s present age; 18 is B''s age at that earlier time.','मान लीजिए अभी A की आयु a और B की b वर्ष है, जहाँ a > b। A की आयु b वर्ष, a - b वर्ष पहले थी, जब B की आयु b - (a - b) = 2b - a थी। अतः a = 2(2b - a), यानी 3a = 4b, और a + b = 63 के साथ b = 27 और a = 36। जाँच: नौ वर्ष पहले A 27 और B 18 वर्ष का था, और 36, 18 का दोगुना है। 42, A को सीधे B की वर्तमान आयु का दोगुना मान लेता है; 27, B की वर्तमान आयु है; 18 उस पहले के समय में B की आयु है।','csat-l2-t03-qa-ph-twice-as-old-as-b-was','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','statement_based','hard','Statement: Of the 200 students in a school, 120 passed in Mathematics and 150 passed in Science.

Which of the following conclusions follow(s) from the statement?','कथन: एक विद्यालय के 200 विद्यार्थियों में से 120 गणित में और 150 विज्ञान में उत्तीर्ण हुए।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथन से निकलता/निकलते है/हैं?','{"statements": ["At least 70 students passed in both subjects.", "At most 120 students passed in both subjects."], "statements_hi": ["कम से कम 70 विद्यार्थी दोनों विषयों में उत्तीर्ण हुए।", "अधिक से अधिक 120 विद्यार्थी दोनों विषयों में उत्तीर्ण हुए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l2-t03", "csat_order": 77}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": false}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": true}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Both follow. Those who passed in at least one subject cannot be more than 200, so those who passed in both are at least 120 + 150 - 200 = 70 (I). And no more students can have passed in both than passed in Mathematics, so the overlap is at most 120 (II), which happens if every Mathematics pass also passed in Science. The trap is to think that a statement with ''at least'' or ''at most'' cannot be certain; both bounds are forced by the numbers.','दोनों निकलते हैं। कम से कम एक विषय में उत्तीर्ण विद्यार्थी 200 से अधिक नहीं हो सकते, इसलिए दोनों में उत्तीर्ण कम से कम 120 + 150 - 200 = 70 हैं (I)। और दोनों में उत्तीर्ण विद्यार्थी गणित में उत्तीर्ण विद्यार्थियों से अधिक नहीं हो सकते, इसलिए यह संख्या अधिक से अधिक 120 है (II), जो तब होता है जब गणित में उत्तीर्ण हर विद्यार्थी विज्ञान में भी उत्तीर्ण हो। जाल यह सोचना है कि ''कम से कम'' या ''अधिक से अधिक'' वाला कथन निश्चित नहीं हो सकता; दोनों सीमाएँ संख्याओं से ही तय होती हैं।','csat-l2-t03-lr-sc-pass-overlap-bounds','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','hard','Vessel A holds milk and water in the ratio 3 : 1, and vessel B holds them in the ratio 5 : 3. In what ratio should the contents of A and B be mixed to get a mixture in which milk and water are in the ratio 2 : 1?','पात्र A में दूध और पानी 3 : 1 के अनुपात में हैं, और पात्र B में 5 : 3 के अनुपात में। A और B की सामग्री को किस अनुपात में मिलाया जाए कि मिश्रण में दूध और पानी 2 : 1 के अनुपात में हों?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 78}'::jsonb,'[{"id": "a", "body": "1 : 2", "body_hi": "1 : 2", "isCorrect": true}, {"id": "b", "body": "1 : 3", "body_hi": "1 : 3", "isCorrect": false}, {"id": "c", "body": "2 : 1", "body_hi": "2 : 1", "isCorrect": false}, {"id": "d", "body": "3 : 5", "body_hi": "3 : 5", "isCorrect": false}]'::jsonb,2.5,0.83,'Work with the fraction of milk: 3/4 in A, 5/8 in B, and 2/3 wanted. By alligation, A : B = (2/3 - 5/8) : (3/4 - 2/3) = 1/24 : 1/12 = 1 : 2. Check: 1 litre of A and 2 of B hold 3/4 + 5/4 = 2 litres of milk in 3, which is 2 : 1. 2 : 1 is the answer the wrong way round; 1 : 3 comes from alligating the ratios 3, 5/3 and 2 as if they were fractions of milk; 3 : 5 simply sets the milk parts of the two vessels against each other.','दूध के अंश से काम कीजिए: A में 3/4, B में 5/8, और चाहिए 2/3। एलिगेशन से A : B = (2/3 - 5/8) : (3/4 - 2/3) = 1/24 : 1/12 = 1 : 2। जाँच: A का 1 लीटर और B के 2 लीटर में 3/4 + 5/4 = 2 लीटर दूध है, 3 लीटर में, यानी 2 : 1। 2 : 1 उत्तर को उलट देता है; 1 : 3 अनुपातों 3, 5/3 और 2 पर ऐसे एलिगेशन करता है मानो वे दूध के अंश हों; 3 : 5 दोनों पात्रों के दूध के भागों को ही आमने-सामने रख देता है।','csat-l2-t03-qa-rm-two-vessels-to-two-to-one','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','easy','Of five boxes P, Q, R, S and T, each of a different weight, P is heavier than Q but lighter than R, S is lighter than Q, and T is heavier than R. Which box is the second lightest?','पाँच डिब्बों P, Q, R, S और T में से, जिनका हर एक का भार अलग है, P, Q से भारी पर R से हल्का है, S, Q से हल्का है, और T, R से भारी है। दूसरा सबसे हल्का डिब्बा कौन-सा है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 79}'::jsonb,'[{"id": "a", "body": "Q", "body_hi": "Q", "isCorrect": true}, {"id": "b", "body": "R", "body_hi": "R", "isCorrect": false}, {"id": "c", "body": "S", "body_hi": "S", "isCorrect": false}, {"id": "d", "body": "T", "body_hi": "T", "isCorrect": false}]'::jsonb,2.5,0.83,'Joining the clues from heaviest to lightest: T is heavier than R, R than P, P than Q, and Q than S, giving T, R, P, Q, S. The second lightest is Q. R is the second heaviest, the answer from counting at the wrong end; S is the lightest and T the heaviest.','भारी से हल्के की ओर सूत्र जोड़ने पर: T, R से भारी है, R, P से, P, Q से, और Q, S से, यानी T, R, P, Q, S। दूसरा सबसे हल्का Q है। R दूसरा सबसे भारी है, जो ग़लत छोर से गिनने पर आता है; S सबसे हल्का और T सबसे भारी है।','csat-l2-t03-lr-sa-second-lightest-box','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','Which one of the following numbers is the largest?','निम्नलिखित संख्याओं में से कौन-सी सबसे बड़ी है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t03", "csat_order": 80}'::jsonb,'[{"id": "a", "body": "6²⁰", "body_hi": "6²⁰", "isCorrect": false}, {"id": "b", "body": "5²⁵", "body_hi": "5²⁵", "isCorrect": false}, {"id": "c", "body": "3⁴⁰", "body_hi": "3⁴⁰", "isCorrect": true}, {"id": "d", "body": "2⁶⁰", "body_hi": "2⁶⁰", "isCorrect": false}]'::jsonb,2.5,0.83,'The exponents 20, 25, 40 and 60 are all multiples of 5, so write each number as a fifth power: 6²⁰ = (6⁴)⁵ = 1296⁵, 5²⁵ = (5⁵)⁵ = 3125⁵, 3⁴⁰ = (3⁸)⁵ = 6561⁵ and 2⁶⁰ = (2¹²)⁵ = 4096⁵. The largest base inside gives the largest number: 3⁴⁰. 2⁶⁰ has the biggest exponent and 6²⁰ the biggest base, which is why each looks largest at first sight.','घातांक 20, 25, 40 और 60 सभी 5 के गुणज हैं, इसलिए हर संख्या को पाँचवीं घात के रूप में लिखिए: 6²⁰ = (6⁴)⁵ = 1296⁵, 5²⁵ = (5⁵)⁵ = 3125⁵, 3⁴⁰ = (3⁸)⁵ = 6561⁵ और 2⁶⁰ = (2¹²)⁵ = 4096⁵। भीतर का सबसे बड़ा आधार सबसे बड़ी संख्या देता है: 3⁴⁰। 2⁶⁰ का घातांक सबसे बड़ा है और 6²⁰ का आधार सबसे बड़ा, इसीलिए पहली नज़र में दोनों सबसे बड़ी लगती हैं।','csat-l2-t03-qa-nt-largest-of-four-powers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft')
returning concept_group_id;
